#!/usr/bin/env bash
# Run the Multica daemon (and so every agent) as a dedicated Linux user, opc-agent,
# instead of the owner's account. Agents run Claude Code with bypassPermissions, so
# whatever this user can read or push, an agent can too.
#
#   sudo bash agent-user.sh setup                 # user, tools, systemd unit (not started)
#   sudo -iu opc-agent claude                     # once: /login, then /exit
#   sudo bash agent-user.sh github <bot-login>    # paste the bot token when asked
#   sudo systemctl enable --now opc-multica-daemon
#
# Idempotent: re-running a step refreshes it. Owner's MULTICA_HOME defaults to
# ~<SUDO_USER>/multica-spike.
set -euo pipefail

AGENT_USER=opc-agent
AGENT_HOME=/home/$AGENT_USER
BIN=/opt/opc-agent/bin
NODE_VERSION=24.21.0
OWNER=${SUDO_USER:?run with sudo from the owner account}
OWNER_HOME=$(getent passwd "$OWNER" | cut -d: -f6)
MULTICA_HOME=${MULTICA_HOME:-$OWNER_HOME/multica-spike}
UNIT=/etc/systemd/system/opc-multica-daemon.service

[[ $EUID -eq 0 ]] || { echo "run with sudo" >&2; exit 1; }
as_agent() { sudo -u "$AGENT_USER" -H env PATH="$BIN:/usr/local/bin:/usr/bin:/bin" "$@"; }

setup() {
  id "$AGENT_USER" &>/dev/null || useradd --create-home --shell /bin/bash "$AGENT_USER"
  chmod 750 "$AGENT_HOME"
  install -d -m 755 "$BIN"

  # Node, from nodejs.org, checked against the published SHA-256 list.
  local node_dir=/opt/node-v$NODE_VERSION tmp
  if [[ ! -x $node_dir/bin/node ]]; then
    tmp=$(mktemp -d)
    curl -fsSL -o "$tmp/node.tar.xz" "https://nodejs.org/dist/v$NODE_VERSION/node-v$NODE_VERSION-linux-x64.tar.xz"
    curl -fsSL "https://nodejs.org/dist/v$NODE_VERSION/SHASUMS256.txt" \
      | grep " node-v$NODE_VERSION-linux-x64.tar.xz\$" | sed "s|  .*|  $tmp/node.tar.xz|" | sha256sum -c -
    install -d "$node_dir"
    tar -xJf "$tmp/node.tar.xz" -C "$node_dir" --strip-components=1
    rm -rf "$tmp"
  fi
  for b in node npm npx; do ln -sfn "$node_dir/bin/$b" "$BIN/$b"; done

  # Pinned copies of the owner's binaries: claude, multica, gitleaks.
  install -m 755 "$(readlink -f "$MULTICA_HOME/bin/claude")" "$BIN/claude"
  install -m 755 "$MULTICA_HOME/bin/multica" "$BIN/multica"
  install -m 755 "$MULTICA_HOME/bin/gitleaks" "$BIN/gitleaks"

  # Multica login with the owner's PAT (the daemon registers the runtime under it).
  install -d -m 700 -o "$AGENT_USER" -g "$AGENT_USER" "$AGENT_HOME/.config/opc"
  install -m 600 -o "$AGENT_USER" -g "$AGENT_USER" "$MULTICA_HOME/.pat" "$AGENT_HOME/.config/opc/multica.pat"
  as_agent sh -c "multica --profile opc --server-url http://localhost:8310 login --token < '$AGENT_HOME/.config/opc/multica.pat'" >/dev/null
  echo "multica: logged in as profile opc"

  cat > "$UNIT" <<EOF
[Unit]
Description=Multica daemon for OPC agents (runs as $AGENT_USER)
After=network-online.target docker.service
Wants=network-online.target

[Service]
User=$AGENT_USER
Group=$AGENT_USER
WorkingDirectory=$AGENT_HOME
Environment=HOME=$AGENT_HOME
Environment=PATH=$BIN:/usr/local/bin:/usr/bin:/bin
Environment=DO_NOT_TRACK=1
ExecStart=$BIN/multica --profile opc daemon start --foreground --no-auto-update --no-auto-reload --device-name fg-server-opc --max-concurrent-tasks 2
Restart=on-failure
RestartSec=10
# Agents see no other home directory, not even with a permissions slip.
ProtectHome=tmpfs
BindPaths=$AGENT_HOME
PrivateTmp=yes
NoNewPrivileges=yes
ProtectSystem=full

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  echo "setup done. Next: sudo -iu $AGENT_USER claude  (run /login, then /exit)"
}

github() {
  local login=${1:?usage: agent-user.sh github <bot-login>} token id
  read -rsp "Paste the token of GitHub user $login (input hidden): " token; echo
  [[ -n $token ]] || { echo "no token" >&2; exit 1; }
  printf '%s' "$token" | as_agent gh auth login --hostname github.com --git-protocol https --with-token
  unset token
  as_agent gh auth setup-git
  [[ $(as_agent gh api user -q .login) == "$login" ]] || { echo "token does not belong to $login" >&2; exit 1; }
  id=$(as_agent gh api user -q .id)
  as_agent git config --global user.name "$login"
  as_agent git config --global user.email "$id+$login@users.noreply.github.com"
  as_agent git config --global init.defaultBranch main
  echo "github: $AGENT_USER now pushes as $login; scopes: $(as_agent gh api -i user 2>/dev/null | grep -i '^x-oauth-scopes' | cut -d: -f2-)"
}

case ${1:-} in
  setup) setup ;;
  github) shift; github "$@" ;;
  *) sed -n '2,12p' "$0"; exit 2 ;;
esac

// mcpTransportOf classifies a server entry for display, and — because the
// client uses it to decide whether the guided form may edit an entry — it must
// not be lossy about an explicit `type`.
//
// An unrecognised explicit type is returned VERBATIM rather than inferred from
// the presence of a `url`. Reporting `{"type":"websocket","url":"wss://…"}` as
// "http" would tell the settings UI the form can express it, and saving from
// that form rewrites the entry to `type: "http"` — silently changing the
// protocol. Only an entry with NO explicit type is inferred from command / url,
// which is lossless because the form writes that same shape back.
func mcpTransportOf(entry json.RawMessage) string {
	var e struct {
		Type    string          `json:"type"`
		Command json.RawMessage `json:"command"`
		URL     json.RawMessage `json:"url"`
	}
	if err := json.Unmarshal(entry, &e); err != nil {
		return "unknown"
	}
	if declared := strings.ToLower(strings.TrimSpace(e.Type)); declared != "" {
		switch declared {
		case "local", "stdio":
			return "stdio"
		case "remote", "http", "streamable-http":
			return "http"
		}
		// `sse` and anything a newer client invents land here unchanged. The
		// response schema keeps transport a free string for exactly this.
		return declared
	}
	if len(e.Command) > 0 {
		return "stdio"
	}
	if len(e.URL) > 0 {
		return "http"
	}
	return "unknown"
}

func workspaceMcpServerToResponse(server db.WorkspaceMcpServer) WorkspaceMcpServerResponse {
	return WorkspaceMcpServerResponse{
		ID:          uuidToString(server.ID),
		WorkspaceID: uuidToString(server.WorkspaceID),
		Name:        server.Name,
		Transport:   mcpTransportOf(server.Config),
		CreatedAt:   timestampToString(server.CreatedAt),
		UpdatedAt:   timestampToString(server.UpdatedAt),
	}
}

// ListWorkspaceMcpServers returns the workspace's MCP library. Member-visible:
// the payload carries no credential material, and an agent owner needs to see
// what is available to add.
func (h *Handler) ListWorkspaceMcpServers(w http.ResponseWriter, r *http.Request) {
	workspaceID := workspaceIDFromURL(r, "id")
	idUUID, ok := parseUUIDOrBadRequest(w, workspaceID, "workspace id")
	if !ok {
		return
	}
	if _, ok := h.workspaceMember(w, r, workspaceID); !ok {
		return
	}
	servers, err := h.Queries.ListWorkspaceMcpServers(r.Context(), idUUID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list workspace MCP servers")
		return
	}
	counts, err := h.Queries.CountWorkspaceMcpServerAgents(r.Context(), idUUID)
	if err != nil {
		writeError(w, http.StatusInternalServerError, "failed to list workspace MCP servers")
		return
	}
	agentCounts := make(map[string]int64, len(counts))
	for _, row := range counts {
		agentCounts[uuidToString(row.ServerID)] = row.AgentCount
	}
	resp := make([]WorkspaceMcpServerResponse, 0, len(servers))
	for _, server := range servers {
		item := workspaceMcpServerToResponse(server)
		count := agentCounts[item.ID]
		item.AgentCount = &count
		resp = append(resp, item)
	}
	writeJSON(w, http.StatusOK, resp)
}

// requireWorkspaceMcpWriter enforces the write gate. The router already
// restricts these routes to owner/admin, but an agent actor running under an
// owner's PAT would satisfy that gate: adding a shared MCP server has to stay a
// human admin action.
func (h *Handler) requireWorkspaceMcpWriter(w http.ResponseWriter, r *http.Request, workspaceID string) bool {
	member, ok := h.workspaceMember(w, r, workspaceID)
	if !ok {
		return false
	}
	if actorType, _ := h.resolveActor(r, requestUserID(r), workspaceID); actorType == "agent" {
		writeError(w, http.StatusForbidden, "agents cannot modify the workspace MCP servers")
		return false
	}
	if !roleAllowed(member.Role, "owner", "admin") {
		writeError(w, http.StatusForbidden, "insufficient permissions")
		return false
	}
	return true
