1	#!/usr/bin/env node
2	// opc: lint, pack and deploy an OPC package to Multica.
3	//
4	// An OPC package is an Agent Companies v1 package (COMPANY.md, teams/, agents/,
5	// projects/, tasks/, skills/) plus the fgopc extension: workflows/<slug>/WORKFLOW.md
6	// and .fgopc.yaml. See ../spec/package-format.md.
7	//
8	//     opc.mjs lint   <package>
9	//     opc.mjs pack   <package> [-o out.tar.gz]
10	//     opc.mjs plan   <package>                 # what deploy would change, no writes
11	//     opc.mjs deploy <package> [--activate-routines]
12	//
13	// Deploy is idempotent: entities are matched by slug through a state file
14	// (<package>/.opc/multica-<workspace>.json), falling back to name. Secret values
15	// come from environment variables named in .fgopc.yaml and are never printed.
16	//
17	// Environment: MULTICA_API (default http://127.0.0.1:8310), MULTICA_TOKEN_FILE
18	// (default $MULTICA_HOME/.pat, MULTICA_HOME default ~/multica-spike).
19	//
20	// Needs only Node 18+: YAML comes from the vendored js-yaml (vendor/js-yaml.mjs).
21	import fs from "node:fs";
22	import os from "node:os";
23	import path from "node:path";
24	import crypto from "node:crypto";
25	import zlib from "node:zlib";
26	import { parseArgs, isDeepStrictEqual } from "node:util";
27	import { load as yamlLoad } from "./vendor/js-yaml.mjs";
28	
29	const SCHEMA = "agentcompanies/v1";
30	const EXT_SCHEMA = "fgopc/v1";
31	const BUILTIN_STATUSES = new Set(["backlog", "todo", "in_progress", "in_review", "done", "blocked", "cancelled"]);
32	const CATEGORIES = ["closed", "done", "started", "unstarted"];
33	const SECRET_PATTERNS = [
34	  /sk-[A-Za-z0-9_-]{20,}/, /ghp_[A-Za-z0-9]{30,}/,
35	  /mul_[A-Za-z0-9]{20,}/, /AKIA[0-9A-Z]{16}/,
36	  /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /xox[bap]-[A-Za-z0-9-]{10,}/,
37	];
38	const TEXT_SUFFIXES = new Set([".md", ".txt", ".yaml", ".yml", ".json", ".py", ".sh", ".js", ".mjs", ".ts", ".csv", ".html"]);
39	const IMAGE_SUFFIXES = new Set([".png", ".jpg", ".jpeg", ".svg", ".gif", ".webp"]);
40	const LOCK_FILE = "company-package.lock.json";
41	
42	class Fatal extends Error {}
43	const die = (msg) => { throw new Fatal(msg); };
44	const has = (obj, key) => obj != null && key != null && Object.hasOwn(obj, key);
45	const q = (v) => `'${v}'`;
46	const len = (s) => [...(s || "")].length; // code points, as Multica counts
47	const same = (a, b) => isDeepStrictEqual(a ?? null, b ?? null);
48	
49	// ------------------------------------------------------------- package model
50	
51	function parseYaml(text, where) {
52	  try {
53	    return yamlLoad(text);
54	  } catch (e) {
55	    die(`${where}: bad YAML: ${e.message}`);
56	  }
57	}
58	
59	/** Split a markdown file into frontmatter, body and the raw text. */
60	function readDoc(file) {
61	  const text = fs.readFileSync(file, "utf8");
62	  if (text.startsWith("---\n")) {
63	    const end = text.indexOf("\n---", 4);
64	    if (end !== -1) {
65	      const meta = parseYaml(text.slice(4, end), `${file}: frontmatter`) || {};
66	      return { meta, body: text.slice(end + 4).replace(/^\n+/, ""), raw: text };
67	    }
68	  }
69	  return { meta: {}, body: text, raw: text };
70	}
71	
72	/** 'agents/lan/AGENTS.md', '../lan/AGENTS.md' or 'lan' -> 'lan'. */
73	function refSlug(ref) {
74	  if (!ref) return null;
75	  const p = String(ref);
76	  return path.extname(p) === ".md" ? path.basename(path.dirname(p)) : path.basename(p);
77	}
78	
79	/** Files under root matching a pattern whose only wildcard is a whole '*' segment. */
80	function glob(root, pattern) {
81	  let rels = [""];
82	  for (const part of pattern.split("/")) {
83	    const next = [];
84	    for (const rel of rels) {
85	      if (part === "*") {
86	        let entries = [];
87	        try { entries = fs.readdirSync(path.join(root, rel)); } catch { continue; }
88	        for (const name of entries) next.push(path.join(rel, name));
89	      } else if (fs.existsSync(path.join(root, rel, part))) {
90	        next.push(path.join(rel, part));
91	      }
92	    }
93	    rels = next;
94	  }
95	  return rels.map((r) => path.join(root, r)).filter((f) => fs.statSync(f).isFile()).sort();
96	}
97	
98	/** All files under dir, skipping any path component named in skip. */
99	function walk(dir, skip = new Set()) {
100	  const out = [];
101	  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
102	    if (skip.has(e.name)) continue;
103	    const p = path.join(dir, e.name);
104	    if (e.isDirectory()) out.push(...walk(p, skip));
105	    else if (e.isFile()) out.push(p);
106	  }
107	  return out.sort();
108	}
109	
110	class Package {
111	  constructor(root) {
112	    this.root = path.resolve(root);
113	    this.errors = [];
114	    this.warnings = [];
115	    const companyFile = path.join(this.root, "COMPANY.md");
116	    if (!fs.existsSync(companyFile)) die(`${this.root}: no COMPANY.md, not a company package`);
117	    ({ meta: this.company, body: this.companyBody } = readDoc(companyFile));
118	    const extFile = path.join(this.root, ".fgopc.yaml");
119	    this.ext = fs.existsSync(extFile) ? parseYaml(fs.readFileSync(extFile, "utf8"), extFile) || {} : {};
120	    this.agents = this.load("agents/*/AGENTS.md");
121	    this.teams = this.load("teams/*/TEAM.md");
122	    this.projects = this.load("projects/*/PROJECT.md");
123	    this.tasks = this.load("tasks/*/TASK.md");
124	    for (const [slug, t] of Object.entries(this.load("projects/*/tasks/*/TASK.md"))) {
125	      if (!has(t.meta, "project")) t.meta.project = path.basename(path.dirname(path.dirname(path.dirname(t.path))));
126	      this.tasks[slug] = t;
127	    }
128	    this.workflows = this.load("workflows/*/WORKFLOW.md");
129	    this.skills = {};
130	    for (const file of glob(this.root, "skills/*/SKILL.md")) {
131	      this.skills[path.basename(path.dirname(file))] = { ...readDoc(file), path: file };
132	    }
133	  }
134	
135	  load(pattern) {
136	    const out = {};
137	    for (const file of glob(this.root, pattern)) {
138	      const { meta, body } = readDoc(file);
139	      out[meta.slug || path.basename(path.dirname(file))] = { meta, body, path: file };
140	    }
141	    return out;
142	  }
143	
144	  get slug() {
145	    return this.company.slug;
146	  }
147	
148	  target(name) {
149	    return (this.ext.targets || {})[name] || {};
150	  }
151	
152	  /** [manager slug, member agent slugs without the manager]. */
153	  teamMembers(slug) {
154	    const meta = this.teams[slug].meta;
155	    const manager = refSlug(meta.manager);
156	    const members = (meta.includes || [])
157	      .filter((i) => String(i).includes("AGENTS.md") || has(this.agents, refSlug(i)))
158	      .map(refSlug);
159	    return [manager, members.filter((m) => m && m !== manager)];
160	  }
161	
162	  isSquad(slug) {
163	    return this.teamMembers(slug)[1].length > 0;
164	  }
165	
166	  agentInstructions(slug) {
167	    const a = this.agents[slug];
168	    const parts = [a.body.trim()];
169	    for (const extra of ["SOUL.md", "RULES.md"]) {
170	      const f = path.join(path.dirname(a.path), extra);
171	      if (fs.existsSync(f)) parts.push(fs.readFileSync(f, "utf8").trim());
172	    }
173	    return parts.filter(Boolean).join("\n\n");
174	  }
175	
176	  files() {
177	    return walk(this.root, new Set([".opc", ".git", "node_modules", "__pycache__"]));
178	  }
179	
180	  rel(file) {
181	    return path.relative(this.root, file).split(path.sep).join("/");
182	  }
183	}
184	
185	// ---------------------------------------------------------------------- lint
186	
187	function lint(pkg) {
188	  const E = pkg.errors, W = pkg.warnings;
189	  const c = pkg.company;
190	  for (const f of ["name", "slug", "description", "schema"]) {
191	    if (!c[f]) E.push(`COMPANY.md: missing ${f}`);
192	  }
193	  if (c.schema && c.schema !== SCHEMA) E.push(`COMPANY.md: schema ${q(c.schema)}, expected ${q(SCHEMA)}`);
194	  if (Object.keys(pkg.ext).length && pkg.ext.schema !== EXT_SCHEMA) E.push(`.fgopc.yaml: schema must be ${q(EXT_SCHEMA)}`);
195	
196	  for (const [slug, s] of Object.entries(pkg.skills)) {
197	    if (s.meta.name !== slug) E.push(`skills/${slug}: SKILL.md name must equal the directory name (Agent Skills)`);
198	    if (!s.meta.description) E.push(`skills/${slug}: SKILL.md needs a description`);
199	  }
200	
201	  for (const [slug, a] of Object.entries(pkg.agents)) {
202	    const m = a.meta;
203	    if (!m.name) E.push(`agents/${slug}: missing name`);
204	    else if (len(m.name) > 64) E.push(`agents/${slug}: name longer than 64 characters`);
205	    for (const sk of m.skills || []) {
206	      if (!has(pkg.skills, sk)) E.push(`agents/${slug}: skill ${q(sk)} not found under skills/`);
207	    }
208	    const rt = refSlug(m.reportsTo);
209	    if (rt && !has(pkg.agents, rt)) E.push(`agents/${slug}: reportsTo ${q(rt)} is not an agent`);
210	    if (!a.body.trim()) W.push(`agents/${slug}: empty instructions body`);
211	  }
212	
213	  for (const slug of Object.keys(pkg.teams)) {
214	    const [manager, members] = pkg.teamMembers(slug);
215	    if (!has(pkg.agents, manager)) E.push(`teams/${slug}: manager ${q(manager)} is not an agent`);
216	    for (const m of members) {
217	      if (!has(pkg.agents, m)) E.push(`teams/${slug}: includes unknown agent ${q(m)}`);
218	    }
219	  }
220	
221	  for (const [slug, p] of Object.entries(pkg.projects)) {
222	    const owner = p.meta.owner;
223	    if (owner && !has(pkg.agents, owner)) E.push(`projects/${slug}: owner ${q(owner)} is not an agent`);
224	  }
225	
226	  for (const [slug, t] of Object.entries(pkg.tasks)) {
227	    const m = t.meta;
228	    const who = m.assignee;
229	    if (who && !has(pkg.agents, who) && !has(pkg.teams, who)) E.push(`tasks/${slug}: assignee ${q(who)} is not an agent or team`);
230	    if (m.project && !has(pkg.projects, m.project)) E.push(`tasks/${slug}: project ${q(m.project)} not found`);
231	    if (m.recurring && !((pkg.ext.routines || {})[slug] || {}).triggers) {
232	      W.push(`tasks/${slug}: recurring but no triggers in .fgopc.yaml routines; deployed without a schedule`);
233	    }
234	    if (!m.recurring) W.push(`tasks/${slug}: one-time tasks are not deployed (only recurring tasks become autopilots)`);
235	  }
236	
237	  const bound = new Set();
238	  for (const [slug, cfg] of Object.entries(pkg.ext.projects || {})) {
239	    if (!has(pkg.projects, slug)) E.push(`.fgopc.yaml projects: ${q(slug)} has no PROJECT.md`);
240	    const wf = (cfg || {}).workflow;
241	    if (wf && !has(pkg.workflows, wf)) E.push(`.fgopc.yaml projects.${slug}: workflow ${q(wf)} not found`);
242	    bound.add(wf);
243	  }
244	
245	  for (const [slug, w] of Object.entries(pkg.workflows)) {
246	    const m = w.meta;
247	    const steps = m.statuses || [];
248	    if (m.kind !== "workflow") E.push(`workflows/${slug}: kind must be 'workflow'`);
249	    if (!steps.length) E.push(`workflows/${slug}: no statuses`);
250	    if (steps.length > 50) E.push(`workflows/${slug}: more than 50 statuses`);
251	    const keys = new Set(steps.map((s) => s.key));
252	    for (const s of steps) {
253	      const k = s.key;
254	      if (!k || !/^[a-z][a-z0-9_]*$/.test(k)) E.push(`workflows/${slug}: bad status key ${q(k)}`);
255	      if (!BUILTIN_STATUSES.has(k)) {
256	        if (!s.name) E.push(`workflows/${slug}.${k}: a new status needs a name`);
257	        if (!CATEGORIES.includes(s.category)) E.push(`workflows/${slug}.${k}: a new status needs category in ${CATEGORIES.join(", ")}`);
258	      }
259	      for (const edge of ["next", "back"]) {
260	        if (s[edge] && !keys.has(s[edge])) E.push(`workflows/${slug}.${k}: ${edge} ${q(s[edge])} is not a status of this workflow`);
261	      }
262	      const h = s.handler || {};
263	      if (has(h, "agent") && !has(pkg.agents, h.agent)) E.push(`workflows/${slug}.${k}: handler agent ${q(h.agent)} not found`);
264	      if (has(h, "team") && !has(pkg.teams, h.team)) E.push(`workflows/${slug}.${k}: handler team ${q(h.team)} not found`);
265	      else if (has(h, "team") && pkg.isSquad(h.team)) W.push(`workflows/${slug}.${k}: Multica cannot hand a step to a squad; it goes to the team manager`);
266	      if (len(s.instructions) > 8000) E.push(`workflows/${slug}.${k}: instructions longer than 8000 characters`);
267	    }
268	    if (m.rules) W.push(`workflows/${slug}: Multica does not enforce rules; they are added to step instructions`);
269	    if (!bound.has(slug)) W.push(`workflows/${slug}: not bound to any project in .fgopc.yaml`);
270	  }
271	
272	  const names = Object.values(pkg.agents).map((a) => a.meta.name);
273	  if (names.length !== new Set(names).size) E.push("agents: names must be unique (Multica matches by name)");
274	
275	  for (const [slug, acfg] of Object.entries(pkg.target("multica").agents || {})) {
276	    if (!has(pkg.agents, slug)) E.push(`.fgopc.yaml targets.multica.agents: ${q(slug)} has no AGENTS.md`);
277	    const pm = (acfg || {}).permission_mode;
278	    if (pm && !["private", "public_to"].includes(pm)) E.push(`.fgopc.yaml targets.multica.agents.${slug}: permission_mode must be private or public_to`);
279	  }
280	
281	  for (const file of pkg.files()) {
282	    const rel = pkg.rel(file);
283	    const base = path.basename(file), ext = path.extname(file);
284	    if ([".env", ".pat", ".jwt"].includes(base) || [".pem", ".key"].includes(ext)) {
285	      E.push(`${rel}: forbidden file in a package`);
286	      continue;
287	    }
288	    if (TEXT_SUFFIXES.has(ext)) {
289	      const text = fs.readFileSync(file, "utf8");
290	      if (SECRET_PATTERNS.some((p) => p.test(text))) E.push(`${rel}: looks like it contains a secret`);
291	    } else if (!IMAGE_SUFFIXES.has(ext) && base !== ".gitignore") {
292	      W.push(`${rel}: executable or binary content; review before import`);
293	    }
294	  }
295	  return E.length === 0;
296	}
297	
298	function printLint(pkg) {
299	  const ok = lint(pkg);
300	  for (const e of pkg.errors) console.log("error:", e);
301	  for (const w of pkg.warnings) console.log("warn: ", w);
302	  const n = (o) => Object.keys(o).length;
303	  console.log(`${pkg.slug}: ${n(pkg.agents)} agents, ${n(pkg.teams)} teams, ${n(pkg.skills)} skills, ` +
304	    `${n(pkg.workflows)} workflows, ${n(pkg.projects)} projects, ${n(pkg.tasks)} tasks -> ${ok ? "ok" : "FAILED"}`);
305	  return ok;
306	}
307	
308	// ---------------------------------------------------------------------- pack
309	
310	/** One ustar header block; long paths use the 155-byte prefix field. */
311	function tarHeader(name, size, mtime) {
312	  const h = Buffer.alloc(512);
313	  let prefix = "";
314	  if (Buffer.byteLength(name) > 100) {
315	    const i = name.lastIndexOf("/", 155);
316	    prefix = name.slice(0, i);
317	    name = name.slice(i + 1);
318	  }
319	  if (Buffer.byteLength(name) > 100 || Buffer.byteLength(prefix) > 155) die(`${prefix}/${name}: path too long for tar`);
320	  const put = (s, off) => h.write(s, off, "utf8");
321	  const octal = (n, width) => Math.floor(n).toString(8).padStart(width - 1, "0") + "\0";
322	  put(name, 0);
323	  put(octal(0o644, 8), 100);
324	  put(octal(0, 8), 108);
325	  put(octal(0, 8), 116);
326	  put(octal(size, 12), 124);
327	  put(octal(mtime, 12), 136);
328	  put(" ".repeat(8), 148);
329	  put("0", 156);
330	  put("ustar\0", 257);
331	  put("00", 263);
332	  put(prefix, 345);
333	  let sum = 0;
334	  for (const b of h) sum += b;
335	  put(sum.toString(8).padStart(6, "0") + "\0 ", 148);
336	  return h;
337	}
