362	class Api {
363	  constructor(base, token) {
364	    this.base = base.replace(/\/+$/, "");
365	    this.token = token;
366	    this.ws = null;
367	  }
368	
369	  async call(method, p, body) {
370	    const headers = { "Content-Type": "application/json", Authorization: "Bearer " + this.token };
371	    if (this.ws) headers["X-Workspace-ID"] = this.ws;
372	    let r;
373	    try {
374	      r = await fetch(this.base + p, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
375	    } catch (e) {
376	      die(`${method} ${p}: ${e.cause?.message || e.message}`);
377	    }
378	    const text = await r.text();
379	    if (!r.ok) die(`${method} ${p} -> ${r.status} ${text.slice(0, 500)}`);
380	    return text ? JSON.parse(text) : null;
381	  }
382	
383	  async list(p, key) {
384	    let d = await this.call("GET", p);
385	    if (d && !Array.isArray(d)) d = key ? d[key] : Object.values(d).find(Array.isArray) || [];
386	    return d || [];
387	  }
388	}
