390	class MulticaDeployer {
391	  constructor(pkg, api, dryRun, activateRoutines = false) {
392	    this.pkg = pkg;
393	    this.api = api;
394	    this.dry = dryRun;
395	    this.activate = activateRoutines;
396	    this.cfg = pkg.target("multica");
397	    this.changes = 0;
398	    this.ids = { agent: {}, squad: {}, skill: {}, workflow: {}, project: {}, autopilot: {} };
399	  }
400	
401	  // -- bookkeeping
402	  log(op, kind, slug, extra = "") {
403	    if (op !== "=") this.changes += 1;
404	    console.log(`${op} ${kind.padEnd(9)} ${slug}${extra ? "  " + extra : ""}`);
405	  }
406	
407	  statePath() {
408	    return path.join(this.pkg.root, ".opc", `multica-${this.wsSlug}.json`);
409	  }
410	
411	  loadState() {
412	    const p = this.statePath();
413	    this.state = fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : {};
414	  }
415	
416	  saveState() {
417	    if (this.dry) return;
418	    const p = this.statePath();
419	    fs.mkdirSync(path.dirname(p), { recursive: true });
420	    fs.writeFileSync(path.join(path.dirname(p), ".gitignore"), "*\n");
421	    const merged = {};
422	    for (const [kind, ids] of Object.entries(this.ids)) {
423	      merged[kind] = { ...(this.state[kind] || {}), ...Object.fromEntries(Object.entries(ids).filter(([, id]) => id)) };
424	    }
425	    fs.writeFileSync(p, JSON.stringify(merged, null, 2) + "\n");
426	  }
427	
428	  /** Existing record for slug: by remembered id, else by name. */
429	  match(kind, slug, existing, name, nameKey = "name") {
430	    const sid = (this.state[kind] || {})[slug];
431	    return existing.find((x) => sid && x.id === sid) ?? existing.find((x) => x[nameKey] === name) ?? null;
432	  }
433	
434	  /** Create or update one entity; returns its id (null for a create in a dry run). */
435	  async upsert(kind, slug, current, desired, create, update, compare = null) {
436	    let rid;
437	    if (current == null) {
438	      this.log("+", kind, slug);
439	      rid = this.dry ? null : (await create(desired)).id;
440	    } else {
441	      rid = current.id;
442	      const diff = (compare || Object.keys(desired)).filter((k) => !same(current[k], desired[k]));
443	      this.log(diff.length ? "~" : "=", kind, slug, diff.join(","));
444	      if (diff.length && !this.dry) await update(rid, desired);
445	    }
446	    this.ids[kind][slug] = rid;
447	    return rid;
448	  }
