499	  async skills() {
500	    const existing = await this.api.list("/api/skills");
501	    for (const [slug, s] of Object.entries(this.pkg.skills)) {
502	      const dir = path.dirname(s.path);
503	      const files = walk(dir)
504	        .filter((f) => path.basename(f) !== "SKILL.md" && TEXT_SUFFIXES.has(path.extname(f)))
505	        .map((f) => ({ path: path.relative(dir, f).split(path.sep).join("/"), content: fs.readFileSync(f, "utf8") }));
506	      const byPath = (fs_) => fs_.map(({ path: p, content }) => ({ path: p, content })).sort((a, b) => a.path.localeCompare(b.path));
507	      // files is part of the diff, so a change to a script or reference alone is deployed too.
508	      const desired = { name: slug, description: s.meta.description || "", content: s.raw, files: byPath(files) };
509	      let cur = this.match("skill", slug, existing, slug);
510	      if (cur && !(has(cur, "content") && has(cur, "files"))) cur = await this.api.call("GET", `/api/skills/${cur.id}`);
511	      if (cur) cur = { ...cur, files: byPath(cur.files || []) };
512	      await this.upsert("skill", slug, cur, desired,
513	        (d) => this.api.call("POST", "/api/skills", d),
514	        (i, d) => this.api.call("PUT", `/api/skills/${i}`, d));
515	    }
516	  }
