32	const CATEGORIES = ["closed", "done", "started", "unstarted"];
33	const SECRET_PATTERNS = [
34	  /sk-[A-Za-z0-9_-]{20,}/, /ghp_[A-Za-z0-9]{30,}/,
35	  /mul_[A-Za-z0-9]{20,}/, /AKIA[0-9A-Z]{16}/,
