59	/** Split a markdown file into frontmatter, body and the raw text. */
60	function readDoc(file) {
61	  const text = fs.readFileSync(file, "utf8");
62	  if (text.startsWith("---\n")) {
63	    const end = text.indexOf("\n---", 4);
64	    if (end !== -1) {
65	      const meta = parseYaml(text.slice(4, end), `${file}: frontmatter`) || {};
66	      return { meta, body: text.slice(end + 4).replace(/^\n+/, ""), raw: text };
67	    }
68	  }
69	  return { meta: {}, body: text, raw: text };
70	}
