72	/** 'agents/lan/AGENTS.md', '../lan/AGENTS.md' or 'lan' -> 'lan'. */
73	function refSlug(ref) {
74	  if (!ref) return null;
75	  const p = String(ref);
76	  return path.extname(p) === ".md" ? path.basename(path.dirname(p)) : path.basename(p);
77	}
