79	/** Files under root matching a pattern whose only wildcard is a whole '*' segment. */
80	function glob(root, pattern) {
81	  let rels = [""];
82	  for (const part of pattern.split("/")) {
83	    const next = [];
84	    for (const rel of rels) {
85	      if (part === "*") {
86	        let entries = [];
87	        try { entries = fs.readdirSync(path.join(root, rel)); } catch { continue; }
88	        for (const name of entries) next.push(path.join(rel, name));
89	      } else if (fs.existsSync(path.join(root, rel, part))) {
90	        next.push(path.join(rel, part));
91	      }
92	    }
93	    rels = next;
94	  }
95	  return rels.map((r) => path.join(root, r)).filter((f) => fs.statSync(f).isFile()).sort();
96	}
97	
98	/** All files under dir, skipping any path component named in skip. */
99	function walk(dir, skip = new Set()) {
100	  const out = [];
101	  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
102	    if (skip.has(e.name)) continue;
103	    const p = path.join(dir, e.name);
104	    if (e.isDirectory()) out.push(...walk(p, skip));
105	    else if (e.isFile()) out.push(p);
106	  }
107	  return out.sort();
108	}
