110	class Package {
111	  constructor(root) {
112	    this.root = path.resolve(root);
113	    this.errors = [];
114	    this.warnings = [];
115	    const companyFile = path.join(this.root, "COMPANY.md");
116	    if (!fs.existsSync(companyFile)) die(`${this.root}: no COMPANY.md, not a company package`);
117	    ({ meta: this.company, body: this.companyBody } = readDoc(companyFile));
118	    const extFile = path.join(this.root, ".fgopc.yaml");
119	    this.ext = fs.existsSync(extFile) ? parseYaml(fs.readFileSync(extFile, "utf8"), extFile) || {} : {};
120	    this.agents = this.load("agents/*/AGENTS.md");
121	    this.teams = this.load("teams/*/TEAM.md");
122	    this.projects = this.load("projects/*/PROJECT.md");
123	    this.tasks = this.load("tasks/*/TASK.md");
124	    for (const [slug, t] of Object.entries(this.load("projects/*/tasks/*/TASK.md"))) {
125	      if (!has(t.meta, "project")) t.meta.project = path.basename(path.dirname(path.dirname(path.dirname(t.path))));
126	      this.tasks[slug] = t;
127	    }
128	    this.workflows = this.load("workflows/*/WORKFLOW.md");
129	    this.skills = {};
130	    for (const file of glob(this.root, "skills/*/SKILL.md")) {
131	      this.skills[path.basename(path.dirname(file))] = { ...readDoc(file), path: file };
132	    }
133	  }
134	
135	  load(pattern) {
136	    const out = {};
137	    for (const file of glob(this.root, pattern)) {
138	      const { meta, body } = readDoc(file);
139	      out[meta.slug || path.basename(path.dirname(file))] = { meta, body, path: file };
140	    }
141	    return out;
142	  }
143	
144	  get slug() {
145	    return this.company.slug;
146	  }
147	
148	  target(name) {
149	    return (this.ext.targets || {})[name] || {};
150	  }
151	
152	  /** [manager slug, member agent slugs without the manager]. */
153	  teamMembers(slug) {
154	    const meta = this.teams[slug].meta;
155	    const manager = refSlug(meta.manager);
156	    const members = (meta.includes || [])
157	      .filter((i) => String(i).includes("AGENTS.md") || has(this.agents, refSlug(i)))
158	      .map(refSlug);
159	    return [manager, members.filter((m) => m && m !== manager)];
160	  }
161	
162	  isSquad(slug) {
163	    return this.teamMembers(slug)[1].length > 0;
164	  }
165	
166	  agentInstructions(slug) {
167	    const a = this.agents[slug];
168	    const parts = [a.body.trim()];
169	    for (const extra of ["SOUL.md", "RULES.md"]) {
170	      const f = path.join(path.dirname(a.path), extra);
171	      if (fs.existsSync(f)) parts.push(fs.readFileSync(f, "utf8").trim());
172	    }
173	    return parts.filter(Boolean).join("\n\n");
174	  }
175	
176	  files() {
177	    return walk(this.root, new Set([".opc", ".git", "node_modules", "__pycache__"]));
178	  }
179	
180	  rel(file) {
181	    return path.relative(this.root, file).split(path.sep).join("/");
182	  }
183	}
