187	function lint(pkg) {
188	  const E = pkg.errors, W = pkg.warnings;
189	  const c = pkg.company;
190	  for (const f of ["name", "slug", "description", "schema"]) {
191	    if (!c[f]) E.push(`COMPANY.md: missing ${f}`);
192	  }
193	  if (c.schema && c.schema !== SCHEMA) E.push(`COMPANY.md: schema ${q(c.schema)}, expected ${q(SCHEMA)}`);
194	  if (Object.keys(pkg.ext).length && pkg.ext.schema !== EXT_SCHEMA) E.push(`.fgopc.yaml: schema must be ${q(EXT_SCHEMA)}`);
195	
196	  for (const [slug, s] of Object.entries(pkg.skills)) {
197	    if (s.meta.name !== slug) E.push(`skills/${slug}: SKILL.md name must equal the directory name (Agent Skills)`);
198	    if (!s.meta.description) E.push(`skills/${slug}: SKILL.md needs a description`);
199	  }
200	
201	  for (const [slug, a] of Object.entries(pkg.agents)) {
202	    const m = a.meta;
203	    if (!m.name) E.push(`agents/${slug}: missing name`);
204	    else if (len(m.name) > 64) E.push(`agents/${slug}: name longer than 64 characters`);
205	    for (const sk of m.skills || []) {
206	      if (!has(pkg.skills, sk)) E.push(`agents/${slug}: skill ${q(sk)} not found under skills/`);
207	    }
208	    const rt = refSlug(m.reportsTo);
209	    if (rt && !has(pkg.agents, rt)) E.push(`agents/${slug}: reportsTo ${q(rt)} is not an agent`);
210	    if (!a.body.trim()) W.push(`agents/${slug}: empty instructions body`);
211	  }
212	
213	  for (const slug of Object.keys(pkg.teams)) {
214	    const [manager, members] = pkg.teamMembers(slug);
215	    if (!has(pkg.agents, manager)) E.push(`teams/${slug}: manager ${q(manager)} is not an agent`);
216	    for (const m of members) {
217	      if (!has(pkg.agents, m)) E.push(`teams/${slug}: includes unknown agent ${q(m)}`);
218	    }
219	  }
220	
221	  for (const [slug, p] of Object.entries(pkg.projects)) {
222	    const owner = p.meta.owner;
223	    if (owner && !has(pkg.agents, owner)) E.push(`projects/${slug}: owner ${q(owner)} is not an agent`);
224	  }
225	
226	  for (const [slug, t] of Object.entries(pkg.tasks)) {
227	    const m = t.meta;
228	    const who = m.assignee;
229	    if (who && !has(pkg.agents, who) && !has(pkg.teams, who)) E.push(`tasks/${slug}: assignee ${q(who)} is not an agent or team`);
230	    if (m.project && !has(pkg.projects, m.project)) E.push(`tasks/${slug}: project ${q(m.project)} not found`);
231	    if (m.recurring && !((pkg.ext.routines || {})[slug] || {}).triggers) {
232	      W.push(`tasks/${slug}: recurring but no triggers in .fgopc.yaml routines; deployed without a schedule`);
233	    }
234	    if (!m.recurring) W.push(`tasks/${slug}: one-time tasks are not deployed (only recurring tasks become autopilots)`);
235	  }
236	
237	  const bound = new Set();
238	  for (const [slug, cfg] of Object.entries(pkg.ext.projects || {})) {
239	    if (!has(pkg.projects, slug)) E.push(`.fgopc.yaml projects: ${q(slug)} has no PROJECT.md`);
240	    const wf = (cfg || {}).workflow;
241	    if (wf && !has(pkg.workflows, wf)) E.push(`.fgopc.yaml projects.${slug}: workflow ${q(wf)} not found`);
242	    bound.add(wf);
243	  }
244	
245	  for (const [slug, w] of Object.entries(pkg.workflows)) {
246	    const m = w.meta;
247	    const steps = m.statuses || [];
248	    if (m.kind !== "workflow") E.push(`workflows/${slug}: kind must be 'workflow'`);
249	    if (!steps.length) E.push(`workflows/${slug}: no statuses`);
250	    if (steps.length > 50) E.push(`workflows/${slug}: more than 50 statuses`);
251	    const keys = new Set(steps.map((s) => s.key));
252	    for (const s of steps) {
253	      const k = s.key;
254	      if (!k || !/^[a-z][a-z0-9_]*$/.test(k)) E.push(`workflows/${slug}: bad status key ${q(k)}`);
255	      if (!BUILTIN_STATUSES.has(k)) {
256	        if (!s.name) E.push(`workflows/${slug}.${k}: a new status needs a name`);
257	        if (!CATEGORIES.includes(s.category)) E.push(`workflows/${slug}.${k}: a new status needs category in ${CATEGORIES.join(", ")}`);
258	      }
259	      for (const edge of ["next", "back"]) {
260	        if (s[edge] && !keys.has(s[edge])) E.push(`workflows/${slug}.${k}: ${edge} ${q(s[edge])} is not a status of this workflow`);
261	      }
262	      const h = s.handler || {};
263	      if (has(h, "agent") && !has(pkg.agents, h.agent)) E.push(`workflows/${slug}.${k}: handler agent ${q(h.agent)} not found`);
264	      if (has(h, "team") && !has(pkg.teams, h.team)) E.push(`workflows/${slug}.${k}: handler team ${q(h.team)} not found`);
265	      else if (has(h, "team") && pkg.isSquad(h.team)) W.push(`workflows/${slug}.${k}: Multica cannot hand a step to a squad; it goes to the team manager`);
266	      if (len(s.instructions) > 8000) E.push(`workflows/${slug}.${k}: instructions longer than 8000 characters`);
267	    }
268	    if (m.rules) W.push(`workflows/${slug}: Multica does not enforce rules; they are added to step instructions`);
269	    if (!bound.has(slug)) W.push(`workflows/${slug}: not bound to any project in .fgopc.yaml`);
270	  }
271	
272	  const names = Object.values(pkg.agents).map((a) => a.meta.name);
273	  if (names.length !== new Set(names).size) E.push("agents: names must be unique (Multica matches by name)");
274	
275	  for (const [slug, acfg] of Object.entries(pkg.target("multica").agents || {})) {
276	    if (!has(pkg.agents, slug)) E.push(`.fgopc.yaml targets.multica.agents: ${q(slug)} has no AGENTS.md`);
277	    const pm = (acfg || {}).permission_mode;
278	    if (pm && !["private", "public_to"].includes(pm)) E.push(`.fgopc.yaml targets.multica.agents.${slug}: permission_mode must be private or public_to`);
279	  }
280	
281	  for (const file of pkg.files()) {
282	    const rel = pkg.rel(file);
283	    const base = path.basename(file), ext = path.extname(file);
284	    if ([".env", ".pat", ".jwt"].includes(base) || [".pem", ".key"].includes(ext)) {
285	      E.push(`${rel}: forbidden file in a package`);
286	      continue;
287	    }
288	    if (TEXT_SUFFIXES.has(ext)) {
289	      const text = fs.readFileSync(file, "utf8");
290	      if (SECRET_PATTERNS.some((p) => p.test(text))) E.push(`${rel}: looks like it contains a secret`);
291	    } else if (!IMAGE_SUFFIXES.has(ext) && base !== ".gitignore") {
292	      W.push(`${rel}: executable or binary content; review before import`);
293	    }
294	  }
295	  return E.length === 0;
296	}
