298	function printLint(pkg) {
299	  const ok = lint(pkg);
300	  for (const e of pkg.errors) console.log("error:", e);
301	  for (const w of pkg.warnings) console.log("warn: ", w);
302	  const n = (o) => Object.keys(o).length;
303	  console.log(`${pkg.slug}: ${n(pkg.agents)} agents, ${n(pkg.teams)} teams, ${n(pkg.skills)} skills, ` +
304	    `${n(pkg.workflows)} workflows, ${n(pkg.projects)} projects, ${n(pkg.tasks)} tasks -> ${ok ? "ok" : "FAILED"}`);
305	  return ok;
306	}
