310	/** One ustar header block; long paths use the 155-byte prefix field. */
311	function tarHeader(name, size, mtime) {
312	  const h = Buffer.alloc(512);
313	  let prefix = "";
314	  if (Buffer.byteLength(name) > 100) {
315	    const i = name.lastIndexOf("/", 155);
316	    prefix = name.slice(0, i);
317	    name = name.slice(i + 1);
318	  }
319	  if (Buffer.byteLength(name) > 100 || Buffer.byteLength(prefix) > 155) die(`${prefix}/${name}: path too long for tar`);
320	  const put = (s, off) => h.write(s, off, "utf8");
321	  const octal = (n, width) => Math.floor(n).toString(8).padStart(width - 1, "0") + "\0";
322	  put(name, 0);
323	  put(octal(0o644, 8), 100);
324	  put(octal(0, 8), 108);
325	  put(octal(0, 8), 116);
326	  put(octal(size, 12), 124);
327	  put(octal(mtime, 12), 136);
328	  put(" ".repeat(8), 148);
329	  put("0", 156);
330	  put("ustar\0", 257);
331	  put("00", 263);
332	  put(prefix, 345);
333	  let sum = 0;
334	  for (const b of h) sum += b;
335	  put(sum.toString(8).padStart(6, "0") + "\0 ", 148);
336	  return h;
337	}
