339	function pack(pkg, out) {
340	  const files = pkg.files().filter((f) => pkg.rel(f) !== LOCK_FILE);
341	  const lock = {
342	    schema: SCHEMA, package: pkg.slug, version: pkg.company.version ?? null,
343	    files: Object.fromEntries(files.map((f) => [pkg.rel(f), crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex")])),
344	  };
345	  const lockBytes = Buffer.from(JSON.stringify(lock, null, 2) + "\n");
346	  fs.writeFileSync(path.join(pkg.root, LOCK_FILE), lockBytes);
347	  const prefix = `${pkg.slug}-${pkg.company.version ?? "0.0.0"}`;
348	  out = out || `${prefix}.tar.gz`;
349	  const blocks = [];
350	  const add = (name, data, mtime) => {
351	    blocks.push(tarHeader(name, data.length, mtime), data, Buffer.alloc((512 - (data.length % 512)) % 512));
352	  };
353	  for (const f of files) add(`${prefix}/${pkg.rel(f)}`, fs.readFileSync(f), fs.statSync(f).mtimeMs / 1000);
354	  add(`${prefix}/${LOCK_FILE}`, lockBytes, Date.now() / 1000);
355	  blocks.push(Buffer.alloc(1024));
356	  fs.writeFileSync(out, zlib.gzipSync(Buffer.concat(blocks)));
357	  console.log(`wrote ${out} (${files.length + 1} files) and ${LOCK_FILE}`);
358	}
