390	class MulticaDeployer {
391	  constructor(pkg, api, dryRun, activateRoutines = false) {
392	    this.pkg = pkg;
393	    this.api = api;
394	    this.dry = dryRun;
395	    this.activate = activateRoutines;
396	    this.cfg = pkg.target("multica");
397	    this.changes = 0;
398	    this.ids = { agent: {}, squad: {}, skill: {}, workflow: {}, project: {}, autopilot: {} };
399	  }
400	
401	  // -- bookkeeping
402	  log(op, kind, slug, extra = "") {
403	    if (op !== "=") this.changes += 1;
404	    console.log(`${op} ${kind.padEnd(9)} ${slug}${extra ? "  " + extra : ""}`);
405	  }
406	
407	  statePath() {
408	    return path.join(this.pkg.root, ".opc", `multica-${this.wsSlug}.json`);
409	  }
410	
411	  loadState() {
412	    const p = this.statePath();
413	    this.state = fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : {};
414	  }
415	
416	  saveState() {
417	    if (this.dry) return;
418	    const p = this.statePath();
419	    fs.mkdirSync(path.dirname(p), { recursive: true });
420	    fs.writeFileSync(path.join(path.dirname(p), ".gitignore"), "*\n");
421	    const merged = {};
422	    for (const [kind, ids] of Object.entries(this.ids)) {
423	      merged[kind] = { ...(this.state[kind] || {}), ...Object.fromEntries(Object.entries(ids).filter(([, id]) => id)) };
424	    }
425	    fs.writeFileSync(p, JSON.stringify(merged, null, 2) + "\n");
426	  }
427	
428	  /** Existing record for slug: by remembered id, else by name. */
429	  match(kind, slug, existing, name, nameKey = "name") {
430	    const sid = (this.state[kind] || {})[slug];
431	    return existing.find((x) => sid && x.id === sid) ?? existing.find((x) => x[nameKey] === name) ?? null;
432	  }
433	
434	  /** Create or update one entity; returns its id (null for a create in a dry run). */
435	  async upsert(kind, slug, current, desired, create, update, compare = null) {
436	    let rid;
437	    if (current == null) {
438	      this.log("+", kind, slug);
439	      rid = this.dry ? null : (await create(desired)).id;
440	    } else {
441	      rid = current.id;
442	      const diff = (compare || Object.keys(desired)).filter((k) => !same(current[k], desired[k]));
443	      this.log(diff.length ? "~" : "=", kind, slug, diff.join(","));
444	      if (diff.length && !this.dry) await update(rid, desired);
445	    }
446	    this.ids[kind][slug] = rid;
447	    return rid;
448	  }
449	
450	  // -- steps
451	  async run() {
452	    const { pkg, api } = this;
453	    this.wsSlug = this.cfg.workspace || pkg.slug;
454	    let ws = (await api.list("/api/workspaces")).find((w) => w.slug === this.wsSlug);
455	    if (!ws) {
456	      this.log("+", "workspace", this.wsSlug);
457	      if (this.dry) {
458	        console.log("(workspace does not exist yet; the rest of the plan assumes an empty workspace)");
459	        this.loadState();
460	        return this.planEmpty();
461	      }
462	      ws = await api.call("POST", "/api/workspaces", {
463	        name: pkg.company.name, slug: this.wsSlug, description: pkg.company.description,
464	        issue_prefix: this.cfg.issue_prefix || this.wsSlug.slice(0, 3).toUpperCase(),
465	      });
466	    } else {
467	      this.log("=", "workspace", this.wsSlug);
468	    }
469	    api.ws = ws.id;
470	    this.loadState();
471	    const me = await api.call("GET", "/api/me");
472	    this.me = me.id || me.user?.id;
473	    try {
474	      await this.skills();
475	      await this.agents();
476	      await this.squads();
477	      await this.statuses();
478	      await this.workflows();
479	      await this.projects();
480	      await this.routines();
481	    } finally {
482	      this.saveState();
483	    }
484	    console.log(`${this.dry ? "plan" : "deploy"}: ${this.changes} change(s) in workspace ${this.wsSlug}`);
485	  }
486	
487	  planEmpty() {
488	    const { pkg } = this;
489	    const squads = Object.keys(pkg.teams).filter((s) => pkg.isSquad(s));
490	    const routines = Object.keys(pkg.tasks).filter((s) => pkg.tasks[s].meta.recurring);
491	    for (const [kind, slugs] of [["skill", Object.keys(pkg.skills)], ["agent", Object.keys(pkg.agents)],
492	      ["squad", squads], ["workflow", Object.keys(pkg.workflows)], ["project", Object.keys(pkg.projects)],
493	      ["autopilot", routines]]) {
494	      for (const slug of slugs) this.log("+", kind, slug);
495	    }
496	    console.log(`plan: ${this.changes} change(s)`);
497	  }
498	
499	  async skills() {
500	    const existing = await this.api.list("/api/skills");
501	    for (const [slug, s] of Object.entries(this.pkg.skills)) {
502	      const dir = path.dirname(s.path);
503	      const files = walk(dir)
504	        .filter((f) => path.basename(f) !== "SKILL.md" && TEXT_SUFFIXES.has(path.extname(f)))
505	        .map((f) => ({ path: path.relative(dir, f).split(path.sep).join("/"), content: fs.readFileSync(f, "utf8") }));
506	      const byPath = (fs_) => fs_.map(({ path: p, content }) => ({ path: p, content })).sort((a, b) => a.path.localeCompare(b.path));
507	      // files is part of the diff, so a change to a script or reference alone is deployed too.
508	      const desired = { name: slug, description: s.meta.description || "", content: s.raw, files: byPath(files) };
509	      let cur = this.match("skill", slug, existing, slug);
510	      if (cur && !(has(cur, "content") && has(cur, "files"))) cur = await this.api.call("GET", `/api/skills/${cur.id}`);
511	      if (cur) cur = { ...cur, files: byPath(cur.files || []) };
512	      await this.upsert("skill", slug, cur, desired,
513	        (d) => this.api.call("POST", "/api/skills", d),
514	        (i, d) => this.api.call("PUT", `/api/skills/${i}`, d));
515	    }
516	  }
517	
518	  runtimeFor(slug, cur) {
519	    const acfg = (this.cfg.agents || {})[slug] || {};
520	    const provider = acfg.provider || (this.cfg.defaults || {}).provider || "claude";
521	    // `runtime` picks one daemon when several serve the workspace: a substring of
522	    // the runtime's name or device, e.g. the --device-name the daemon was started with.
523	    const want = acfg.runtime ?? (this.cfg.defaults || {}).runtime;
524	    const rts = this.runtimes.filter((r) => r.provider === provider &&
525	      (!want || [r.name, r.custom_name, r.device_info].some((s) => (s || "").includes(want))));
526	    const online = rts.filter((r) => r.status === "online");
527	    const pick = online.length ? online : rts;
528	    if (!pick.length) {
529	      if (this.dry) return [null, acfg];
530	      die(`agent ${slug}: no ${q(provider)} runtime${want ? ` matching ${q(want)}` : ""} in this workspace; start the daemon first`);
531	    }
532	    // Never move an agent between daemons by accident: they can run as different users.
533	    if (cur && rts.some((r) => r.id === cur.runtime_id)) return [cur.runtime_id, acfg];
534	    if (pick.length > 1) {
535	      die(`agent ${slug}: ${pick.length} ${q(provider)} runtimes (${pick.map((r) => r.name).join(", ")}); ` +
536	        `set targets.multica.defaults.runtime or agents.${slug}.runtime in .fgopc.yaml`);
537	    }
538	    return [pick[0].id, acfg];
539	  }
540	
541	  async agents() {
542	    this.runtimes = await this.api.list("/api/runtimes");
543	    const existing = await this.api.list("/api/agents");
544	    const defaults = this.cfg.defaults || {};
545	    for (const [slug, a] of Object.entries(this.pkg.agents)) {
546	      const m = a.meta;
547	      const cur = this.match("agent", slug, existing, m.name);
548	      const [runtimeId, acfg] = this.runtimeFor(slug, cur);
549	      const desired = {
550	        name: m.name,
551	        description: m.title || m.description || "",
552	        instructions: this.pkg.agentInstructions(slug),
553	        model: acfg.model ?? defaults.model ?? "",
554	        runtime_id: runtimeId,
555	        max_concurrent_tasks: acfg.max_concurrent_tasks ?? defaults.max_concurrent_tasks ?? 1,
556	      };
557	      // Only managed when the package sets it, so hand-made sharing is left alone.
558	      if (acfg.permission_mode) desired.permission_mode = acfg.permission_mode;
559	      const rid = await this.upsert("agent", slug, cur, desired,
560	        (d) => this.api.call("POST", "/api/agents", { ...d, visibility: d.permission_mode === "private" ? "private" : "workspace" }),
561	        (i, d) => this.api.call("PUT", `/api/agents/${i}`, d));
562	      const want = (m.skills || []).map((s) => this.ids.skill[s]).sort();
563	      const haveIds = ((cur || {}).skills || []).map((s) => s.id).sort();
564	      if (!same(want, haveIds)) {
565	        this.log("~", "skills", slug, (m.skills || []).join(",") || "(none)");
566	        if (!this.dry && rid) await this.api.call("PUT", `/api/agents/${rid}/skills`, { skill_ids: want });
567	      }
568	      await this.secrets(slug, rid);
569	    }
570	  }
571	
572	  async secrets(slug, rid) {
573	    const env = {};
574	    for (const sec of this.pkg.ext.secrets || []) {
575	      if (!(sec.agents || []).includes(slug)) continue;
576	      const value = process.env[sec.env];
577	      if (value) env[sec.env] = value;
578	      else console.log(`! secret    ${slug}  ${sec.env} not set in the environment${sec.required ? " (required)" : ""}; left unchanged`);
579	    }
580	    const names = Object.keys(env).sort();
581	    if (names.length) {
582	      this.log("~", "secrets", slug, names.join(","));
583	      if (!this.dry && rid) await this.api.call("PUT", `/api/agents/${rid}/env`, { custom_env: env });
584	    }
585	  }
586	
587	  async squads() {
588	    const existing = await this.api.list("/api/squads");
589	    for (const [slug, t] of Object.entries(this.pkg.teams)) {
590	      if (!this.pkg.isSquad(slug)) continue;
591	      const [manager, members] = this.pkg.teamMembers(slug);
592	      const desired = { name: t.meta.name || slug, description: t.meta.description || "", leader_id: this.ids.agent[manager] };
593	      const cur = this.match("squad", slug, existing, desired.name);
594	      const rid = await this.upsert("squad", slug, cur, desired,
595	        (d) => this.api.call("POST", "/api/squads", d),
596	        (i, d) => this.api.call("PUT", `/api/squads/${i}`, d));
597	      const have = new Map();
598	      if (rid && cur) for (const m of await this.api.list(`/api/squads/${rid}/members`)) have.set(m.member_id, m);
599	      for (const mslug of members) {
600	        const aid = this.ids.agent[mslug];
601	        const role = this.pkg.agents[mslug].meta.title || "";
602	        if (!aid || !have.has(aid)) {
603	          this.log("+", "member", `${slug}/${mslug}`);
604	          if (!this.dry && rid) await this.api.call("POST", `/api/squads/${rid}/members`, { member_type: "agent", member_id: aid, role });
605	        } else if (have.get(aid).role !== role) {
606	          this.log("~", "member", `${slug}/${mslug}`, "role");
607	          if (!this.dry) await this.api.call("PATCH", `/api/squads/${rid}/members/role`, { member_type: "agent", member_id: aid, role });
608	        }
609	      }
610	      const wanted = new Set([...members.map((m) => this.ids.agent[m]), desired.leader_id]);
611	      for (const [aid, mem] of have) {
612	        if (wanted.has(aid)) continue;
613	        this.log("-", "member", `${slug}/${aid.slice(0, 8)}`);
614	        if (!this.dry) await this.api.call("DELETE", `/api/squads/${rid}/members`, { member_type: mem.member_type || "agent", member_id: aid });
615	      }
616	    }
617	  }
618	
619	  async statuses() {
620	    const have = new Set((await this.api.list("/api/issue-statuses", "statuses")).map((s) => s.key));
621	    for (const w of Object.values(this.pkg.workflows)) {
622	      for (const s of w.meta.statuses || []) {
623	        if (have.has(s.key) || BUILTIN_STATUSES.has(s.key)) continue;
624	        have.add(s.key);
625	        this.log("+", "status", s.key);
626	        if (!this.dry) {
627	          await this.api.call("POST", "/api/issue-statuses", { key: s.key, name: s.name, category: s.category, color: s.color || "#8b5cf6" });
628	        }
629	      }
630	    }
631	  }
632	
633	  handler(h) {
634	    if (!h) return { type: "none" };
635	    if (has(h, "agent")) return { type: "agent", id: this.ids.agent[h.agent] };
636	    if (has(h, "team")) {
637	      // Multica rejects squad handoffs (a squad routes its own work), so a
638	      // team step goes to its manager, whose instructions delegate by @mention.
639	      return { type: "agent", id: this.ids.agent[this.pkg.teamMembers(h.team)[0]] };
640	    }
641	    if (h.role === "owner" || h.member === "me") return { type: "member", id: this.me };
642	    if (h.role === "project_lead") return { type: "project_lead" };
643	    die(`unsupported handler ${JSON.stringify(h)}`);
644	  }
645	
646	  static ruleText(rules) {
647	    const out = [];
648	    if ((rules || {}).done_requires === "human") out.push("Không tự chuyển issue sang done; chỉ người mới được đóng issue.");
649	    if ((rules || {}).max_send_backs) out.push(`Nếu issue đã bị trả lại ${rules.max_send_backs} lần, dừng lại và hỏi chủ trong comment.`);
650	    return out.join(" ");
651	  }
652	
653	  async workflows() {
654	    const existing = await this.api.list("/api/issue-workflows");
655	    for (const [slug, w] of Object.entries(this.pkg.workflows)) {
656	      const m = w.meta;
657	      const rules = MulticaDeployer.ruleText(m.rules);
658	      const steps = m.statuses.map((s) => {
659	        const h = this.handler(s.handler);
660	        let instr = (s.instructions || "").trim();
661	        if (rules && h.type === "agent") instr = `${instr}\n${rules}`.trim();
662	        return { status_key: s.key, handler: h, instructions: instr, next_status_key: s.next || "", back_status_key: s.back || "" };
663	      });
664	      const desired = { name: m.name || slug, description: [...(m.description || "")].slice(0, 256).join(""), steps };
665	      let cur = this.match("workflow", slug, existing, desired.name);
666	      if (cur) cur = { ...cur, steps: MulticaDeployer.normalizeSteps(cur.steps || [], new Set(steps.map((s) => s.status_key))) };
667	      await this.upsert("workflow", slug, cur, desired,
668	        (d) => this.api.call("POST", "/api/issue-workflows", d),
669	        (i, d) => this.api.call("PATCH", `/api/issue-workflows/${i}`, d));
670	    }
671	  }
672	
673	  /** Server steps in the request shape; drops fixed statuses Multica adds itself. */
674	  static normalizeSteps(steps, wantedKeys) {
675	    return steps
676	      .filter((s) => !(s.status_key === "cancelled" && !wantedKeys.has(s.status_key)))
677	      .map((s) => {
678	        const h = s.handler || { type: "none" };
679	        return {
680	          status_key: s.status_key,
681	          handler: Object.fromEntries(Object.entries(h).filter(([k, v]) => ["type", "id"].includes(k) && v)),
682	          instructions: s.instructions || "",
683	          next_status_key: s.next_status_key || "",
684	          back_status_key: s.back_status_key || "",
685	        };
686	      });
687	  }
688	
689	  async projects() {
690	    const existing = await this.api.list("/api/projects");
691	    const bindings = this.pkg.ext.projects || {};
692	    for (const [slug, p] of Object.entries(this.pkg.projects)) {
693	      const m = p.meta;
694	      const desired = { title: m.name || slug, description: m.description || [...p.body.trim()].slice(0, 2000).join("") };
695	      if (m.owner) Object.assign(desired, { lead_type: "agent", lead_id: this.ids.agent[m.owner] });
696	      const cur = this.match("project", slug, existing, desired.title, "title");
697	      const rid = await this.upsert("project", slug, cur, desired,
698	        (d) => this.api.call("POST", "/api/projects", d),
699	        (i, d) => this.api.call("PUT", `/api/projects/${i}`, d));
700	      const wf = (bindings[slug] || {}).workflow;
701	      if (!wf) continue;
702	      const wid = this.ids.workflow[wf];
703	      if (!cur || cur.workflow_id !== wid || !wid) {
704	        this.log("~", "binding", `${slug} -> ${wf}`);
705	        if (!this.dry && rid) await this.api.call("POST", `/api/projects/${rid}/workflow`, { workflow_id: wid });
706	      }
707	    }
708	  }
709	
710	  async routines() {
711	    const { pkg } = this;
712	    const existing = await this.api.list("/api/autopilots");
713	    const rcfg = pkg.ext.routines || {};
714	    for (const [slug, t] of Object.entries(pkg.tasks)) {
715	      const m = t.meta;
716	      if (!m.recurring) continue;
717	      const who = m.assignee;
718	      let atype, aid;
719	      if (has(pkg.teams, who) && pkg.isSquad(who)) {
720	        [atype, aid] = ["squad", this.ids.squad[who]];
721	      } else {
722	        const aslug = has(pkg.teams, who) ? pkg.teamMembers(who)[0] : who;
723	        [atype, aid] = ["agent", this.ids.agent[aslug]];
724	      }
725	      const desired = {
726	        title: m.name || slug, description: t.body.trim(), project_id: this.ids.project[m.project],
727	        assignee_type: atype, assignee_id: aid, execution_mode: "create_issue",
728	      };
729	      const cur = this.match("autopilot", slug, existing, desired.title, "title");
730	      const rid = await this.upsert("autopilot", slug, cur, desired,
731	        (d) => this.api.call("POST", "/api/autopilots", d),
732	        (i, d) => this.api.call("PATCH", `/api/autopilots/${i}`, d),
733	        ["title", "description", "project_id", "assignee_type", "assignee_id"]);
734	      if (!cur && !this.dry && rid && !this.activate) {
735	        await this.api.call("PATCH", `/api/autopilots/${rid}`, { status: "paused" });
736	        console.log(`  autopilot ${slug} created paused; enable it in Multica or deploy with --activate-routines`);
737	      }
738	      const have = !cur || !rid ? [] : ((await this.api.call("GET", `/api/autopilots/${rid}`)).triggers || []);
739	      for (const trig of (rcfg[slug] || {}).triggers || []) {
740	        const cron = trig.cron, tz = trig.timezone || "Asia/Ho_Chi_Minh";
741	        if (have.some((h) => h.cron_expression === cron)) continue;
742	        this.log("+", "trigger", `${slug} ${cron} ${tz}`);
743	        if (!this.dry && rid) {
744	          await this.api.call("POST", `/api/autopilots/${rid}/triggers`, { kind: "schedule", cron_expression: cron, timezone: tz });
745	        }
746	      }
747	    }
748	  }
749	}
750	
751	function multicaApi() {
752	  const home = (process.env.MULTICA_HOME || "~/multica-spike").replace(/^~(?=$|\/)/, os.homedir());
753	  const tokenFile = process.env.MULTICA_TOKEN_FILE || path.join(home, ".pat");
754	  if (!fs.existsSync(tokenFile)) die(`${tokenFile}: no token; run multica/stack/bootstrap.py first`);
755	  return new Api(process.env.MULTICA_API || "http://127.0.0.1:8310", fs.readFileSync(tokenFile, "utf8").trim());
756	}
757	
758	const USAGE = `usage: opc.mjs lint   <package>
759	       opc.mjs pack   <package> [-o out.tar.gz]
760	       opc.mjs plan   <package> [--target multica]
761	       opc.mjs deploy <package> [--target multica] [--activate-routines]`;
762	
763	async function main() {
764	  const { values: opts, positionals } = parseArgs({
765	    allowPositionals: true,
766	    options: {
767	      out: { type: "string", short: "o" },
768	      target: { type: "string", default: "multica" },
769	      "activate-routines": { type: "boolean", default: false },
770	      help: { type: "boolean", short: "h" },
771	    },
772	  });
773	  const [cmd, dir] = positionals;
774	  if (opts.help) return console.log(USAGE);
775	  if (!["lint", "pack", "plan", "deploy"].includes(cmd) || !dir || positionals.length > 2) {
776	    console.error(USAGE);
777	    process.exit(2);
778	  }
779	  if (opts.target !== "multica") die(`--target ${opts.target}: only 'multica' is supported`);
780	  const pkg = new Package(dir);
781	  const ok = printLint(pkg);
782	  if (cmd === "lint") process.exit(ok ? 0 : 1);
783	  if (!ok) die("lint failed; fix the errors first");
784	  if (cmd === "pack") return pack(pkg, opts.out);
785	  await new MulticaDeployer(pkg, multicaApi(), cmd === "plan", opts["activate-routines"]).run();
786	}
787	
788	main().catch((e) => {
789	  if (!(e instanceof Fatal) && e.code !== "ERR_PARSE_ARGS_UNKNOWN_OPTION") throw e;
790	  console.error(e.message);
791	  process.exit(1);
792	});
