#!/usr/bin/env node
// opc: lint, pack and deploy an OPC package to Multica.
//
// An OPC package is an Agent Companies v1 package (COMPANY.md, teams/, agents/,
// projects/, tasks/, skills/) plus the fgopc extension: workflows/<slug>/WORKFLOW.md
// and .fgopc.yaml. See ../spec/package-format.md.
//
//     opc.mjs lint   <package>
//     opc.mjs pack   <package> [-o out.tar.gz]
//     opc.mjs plan   <package>                 # what deploy would change, no writes
//     opc.mjs deploy <package> [--activate-routines]
//
// Deploy is idempotent: entities are matched by slug through a state file
// (<package>/.opc/multica-<workspace>.json), falling back to name. Secret values
// come from environment variables named in .fgopc.yaml and are never printed.
//
// Environment: MULTICA_API (default http://127.0.0.1:8310), MULTICA_TOKEN_FILE
// (default $MULTICA_HOME/.pat, MULTICA_HOME default ~/multica-spike).
//
// Needs only Node 18+: YAML comes from the vendored js-yaml (vendor/js-yaml.mjs).
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";
import { parseArgs, isDeepStrictEqual } from "node:util";
import { load as yamlLoad } from "./vendor/js-yaml.mjs";

const SCHEMA = "agentcompanies/v1";
const EXT_SCHEMA = "fgopc/v1";
const BUILTIN_STATUSES = new Set(["backlog", "todo", "in_progress", "in_review", "done", "blocked", "cancelled"]);
const CATEGORIES = ["closed", "done", "started", "unstarted"];
const SECRET_PATTERNS = [
  /sk-[A-Za-z0-9_-]{20,}/, /ghp_[A-Za-z0-9]{30,}/,
  /mul_[A-Za-z0-9]{20,}/, /AKIA[0-9A-Z]{16}/,
  /-----BEGIN [A-Z ]*PRIVATE KEY-----/, /xox[bap]-[A-Za-z0-9-]{10,}/,
];
const TEXT_SUFFIXES = new Set([".md", ".txt", ".yaml", ".yml", ".json", ".py", ".sh", ".js", ".mjs", ".ts", ".csv", ".html"]);
const IMAGE_SUFFIXES = new Set([".png", ".jpg", ".jpeg", ".svg", ".gif", ".webp"]);
const LOCK_FILE = "company-package.lock.json";

class Fatal extends Error {}
const die = (msg) => { throw new Fatal(msg); };
const has = (obj, key) => obj != null && key != null && Object.hasOwn(obj, key);
const q = (v) => `'${v}'`;
const len = (s) => [...(s || "")].length; // code points, as Multica counts
const same = (a, b) => isDeepStrictEqual(a ?? null, b ?? null);

// ------------------------------------------------------------- package model

function parseYaml(text, where) {
  try {
    return yamlLoad(text);
  } catch (e) {
    die(`${where}: bad YAML: ${e.message}`);
  }
}

/** Split a markdown file into frontmatter, body and the raw text. */
function readDoc(file) {
  const text = fs.readFileSync(file, "utf8");
  if (text.startsWith("---\n")) {
    const end = text.indexOf("\n---", 4);
    if (end !== -1) {
      const meta = parseYaml(text.slice(4, end), `${file}: frontmatter`) || {};
      return { meta, body: text.slice(end + 4).replace(/^\n+/, ""), raw: text };
    }
  }
  return { meta: {}, body: text, raw: text };
}

/** 'agents/lan/AGENTS.md', '../lan/AGENTS.md' or 'lan' -> 'lan'. */
function refSlug(ref) {
  if (!ref) return null;
  const p = String(ref);
  return path.extname(p) === ".md" ? path.basename(path.dirname(p)) : path.basename(p);
}

/** Files under root matching a pattern whose only wildcard is a whole '*' segment. */
function glob(root, pattern) {
  let rels = [""];
  for (const part of pattern.split("/")) {
    const next = [];
    for (const rel of rels) {
      if (part === "*") {
        let entries = [];
        try { entries = fs.readdirSync(path.join(root, rel)); } catch { continue; }
        for (const name of entries) next.push(path.join(rel, name));
      } else if (fs.existsSync(path.join(root, rel, part))) {
        next.push(path.join(rel, part));
      }
    }
    rels = next;
  }
  return rels.map((r) => path.join(root, r)).filter((f) => fs.statSync(f).isFile()).sort();
}

/** All files under dir, skipping any path component named in skip. */
function walk(dir, skip = new Set()) {
  const out = [];
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    if (skip.has(e.name)) continue;
    const p = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...walk(p, skip));
    else if (e.isFile()) out.push(p);
  }
  return out.sort();
}

class Package {
  constructor(root) {
    this.root = path.resolve(root);
    this.errors = [];
    this.warnings = [];
    const companyFile = path.join(this.root, "COMPANY.md");
    if (!fs.existsSync(companyFile)) die(`${this.root}: no COMPANY.md, not a company package`);
    ({ meta: this.company, body: this.companyBody } = readDoc(companyFile));
    const extFile = path.join(this.root, ".fgopc.yaml");
    this.ext = fs.existsSync(extFile) ? parseYaml(fs.readFileSync(extFile, "utf8"), extFile) || {} : {};
    this.agents = this.load("agents/*/AGENTS.md");
    this.teams = this.load("teams/*/TEAM.md");
    this.projects = this.load("projects/*/PROJECT.md");
    this.tasks = this.load("tasks/*/TASK.md");
    for (const [slug, t] of Object.entries(this.load("projects/*/tasks/*/TASK.md"))) {
      if (!has(t.meta, "project")) t.meta.project = path.basename(path.dirname(path.dirname(path.dirname(t.path))));
      this.tasks[slug] = t;
    }
    this.workflows = this.load("workflows/*/WORKFLOW.md");
    this.skills = {};
    for (const file of glob(this.root, "skills/*/SKILL.md")) {
      this.skills[path.basename(path.dirname(file))] = { ...readDoc(file), path: file };
    }
  }

  load(pattern) {
    const out = {};
    for (const file of glob(this.root, pattern)) {
      const { meta, body } = readDoc(file);
      out[meta.slug || path.basename(path.dirname(file))] = { meta, body, path: file };
    }
    return out;
  }

  get slug() {
    return this.company.slug;
  }

  target(name) {
    return (this.ext.targets || {})[name] || {};
  }

  /** [manager slug, member agent slugs without the manager]. */
  teamMembers(slug) {
    const meta = this.teams[slug].meta;
    const manager = refSlug(meta.manager);
    const members = (meta.includes || [])
      .filter((i) => String(i).includes("AGENTS.md") || has(this.agents, refSlug(i)))
      .map(refSlug);
    return [manager, members.filter((m) => m && m !== manager)];
  }

  isSquad(slug) {
    return this.teamMembers(slug)[1].length > 0;
  }

  agentInstructions(slug) {
    const a = this.agents[slug];
    const parts = [a.body.trim()];
    for (const extra of ["SOUL.md", "RULES.md"]) {
      const f = path.join(path.dirname(a.path), extra);
      if (fs.existsSync(f)) parts.push(fs.readFileSync(f, "utf8").trim());
    }
    return parts.filter(Boolean).join("\n\n");
  }

  files() {
    return walk(this.root, new Set([".opc", ".git", "node_modules", "__pycache__"]));
  }

  rel(file) {
    return path.relative(this.root, file).split(path.sep).join("/");
  }
}

// ---------------------------------------------------------------------- lint

function lint(pkg) {
  const E = pkg.errors, W = pkg.warnings;
  const c = pkg.company;
  for (const f of ["name", "slug", "description", "schema"]) {
    if (!c[f]) E.push(`COMPANY.md: missing ${f}`);
  }
  if (c.schema && c.schema !== SCHEMA) E.push(`COMPANY.md: schema ${q(c.schema)}, expected ${q(SCHEMA)}`);
  if (Object.keys(pkg.ext).length && pkg.ext.schema !== EXT_SCHEMA) E.push(`.fgopc.yaml: schema must be ${q(EXT_SCHEMA)}`);

  for (const [slug, s] of Object.entries(pkg.skills)) {
    if (s.meta.name !== slug) E.push(`skills/${slug}: SKILL.md name must equal the directory name (Agent Skills)`);
    if (!s.meta.description) E.push(`skills/${slug}: SKILL.md needs a description`);
  }

  for (const [slug, a] of Object.entries(pkg.agents)) {
    const m = a.meta;
    if (!m.name) E.push(`agents/${slug}: missing name`);
    else if (len(m.name) > 64) E.push(`agents/${slug}: name longer than 64 characters`);
    for (const sk of m.skills || []) {
      if (!has(pkg.skills, sk)) E.push(`agents/${slug}: skill ${q(sk)} not found under skills/`);
    }
    const rt = refSlug(m.reportsTo);
    if (rt && !has(pkg.agents, rt)) E.push(`agents/${slug}: reportsTo ${q(rt)} is not an agent`);
    if (!a.body.trim()) W.push(`agents/${slug}: empty instructions body`);
  }

  for (const slug of Object.keys(pkg.teams)) {
    const [manager, members] = pkg.teamMembers(slug);
    if (!has(pkg.agents, manager)) E.push(`teams/${slug}: manager ${q(manager)} is not an agent`);
    for (const m of members) {
      if (!has(pkg.agents, m)) E.push(`teams/${slug}: includes unknown agent ${q(m)}`);
    }
  }

  for (const [slug, p] of Object.entries(pkg.projects)) {
    const owner = p.meta.owner;
    if (owner && !has(pkg.agents, owner)) E.push(`projects/${slug}: owner ${q(owner)} is not an agent`);
  }

  for (const [slug, t] of Object.entries(pkg.tasks)) {
    const m = t.meta;
    const who = m.assignee;
    if (who && !has(pkg.agents, who) && !has(pkg.teams, who)) E.push(`tasks/${slug}: assignee ${q(who)} is not an agent or team`);
    if (m.project && !has(pkg.projects, m.project)) E.push(`tasks/${slug}: project ${q(m.project)} not found`);
    if (m.recurring && !((pkg.ext.routines || {})[slug] || {}).triggers) {
      W.push(`tasks/${slug}: recurring but no triggers in .fgopc.yaml routines; deployed without a schedule`);
    }
    if (!m.recurring) W.push(`tasks/${slug}: one-time tasks are not deployed (only recurring tasks become autopilots)`);
  }

  const bound = new Set();
  for (const [slug, cfg] of Object.entries(pkg.ext.projects || {})) {
    if (!has(pkg.projects, slug)) E.push(`.fgopc.yaml projects: ${q(slug)} has no PROJECT.md`);
    const wf = (cfg || {}).workflow;
    if (wf && !has(pkg.workflows, wf)) E.push(`.fgopc.yaml projects.${slug}: workflow ${q(wf)} not found`);
    bound.add(wf);
  }

  for (const [slug, w] of Object.entries(pkg.workflows)) {
    const m = w.meta;
    const steps = m.statuses || [];
    if (m.kind !== "workflow") E.push(`workflows/${slug}: kind must be 'workflow'`);
    if (!steps.length) E.push(`workflows/${slug}: no statuses`);
    if (steps.length > 50) E.push(`workflows/${slug}: more than 50 statuses`);
    const keys = new Set(steps.map((s) => s.key));
    for (const s of steps) {
      const k = s.key;
      if (!k || !/^[a-z][a-z0-9_]*$/.test(k)) E.push(`workflows/${slug}: bad status key ${q(k)}`);
      if (!BUILTIN_STATUSES.has(k)) {
        if (!s.name) E.push(`workflows/${slug}.${k}: a new status needs a name`);
        if (!CATEGORIES.includes(s.category)) E.push(`workflows/${slug}.${k}: a new status needs category in ${CATEGORIES.join(", ")}`);
      }
      for (const edge of ["next", "back"]) {
        if (s[edge] && !keys.has(s[edge])) E.push(`workflows/${slug}.${k}: ${edge} ${q(s[edge])} is not a status of this workflow`);
      }
      const h = s.handler || {};
      if (has(h, "agent") && !has(pkg.agents, h.agent)) E.push(`workflows/${slug}.${k}: handler agent ${q(h.agent)} not found`);
      if (has(h, "team") && !has(pkg.teams, h.team)) E.push(`workflows/${slug}.${k}: handler team ${q(h.team)} not found`);
      else if (has(h, "team") && pkg.isSquad(h.team)) W.push(`workflows/${slug}.${k}: Multica cannot hand a step to a squad; it goes to the team manager`);
      if (len(s.instructions) > 8000) E.push(`workflows/${slug}.${k}: instructions longer than 8000 characters`);
    }
    if (m.rules) W.push(`workflows/${slug}: Multica does not enforce rules; they are added to step instructions`);
    if (!bound.has(slug)) W.push(`workflows/${slug}: not bound to any project in .fgopc.yaml`);
  }

  const names = Object.values(pkg.agents).map((a) => a.meta.name);
  if (names.length !== new Set(names).size) E.push("agents: names must be unique (Multica matches by name)");

  for (const [slug, acfg] of Object.entries(pkg.target("multica").agents || {})) {
    if (!has(pkg.agents, slug)) E.push(`.fgopc.yaml targets.multica.agents: ${q(slug)} has no AGENTS.md`);
    const pm = (acfg || {}).permission_mode;
    if (pm && !["private", "public_to"].includes(pm)) E.push(`.fgopc.yaml targets.multica.agents.${slug}: permission_mode must be private or public_to`);
  }

  for (const file of pkg.files()) {
    const rel = pkg.rel(file);
    const base = path.basename(file), ext = path.extname(file);
    if ([".env", ".pat", ".jwt"].includes(base) || [".pem", ".key"].includes(ext)) {
      E.push(`${rel}: forbidden file in a package`);
      continue;
    }
    if (TEXT_SUFFIXES.has(ext)) {
      const text = fs.readFileSync(file, "utf8");
      if (SECRET_PATTERNS.some((p) => p.test(text))) E.push(`${rel}: looks like it contains a secret`);
    } else if (!IMAGE_SUFFIXES.has(ext) && base !== ".gitignore") {
      W.push(`${rel}: executable or binary content; review before import`);
    }
  }
  return E.length === 0;
}

function printLint(pkg) {
  const ok = lint(pkg);
  for (const e of pkg.errors) console.log("error:", e);
  for (const w of pkg.warnings) console.log("warn: ", w);
  const n = (o) => Object.keys(o).length;
  console.log(`${pkg.slug}: ${n(pkg.agents)} agents, ${n(pkg.teams)} teams, ${n(pkg.skills)} skills, ` +
    `${n(pkg.workflows)} workflows, ${n(pkg.projects)} projects, ${n(pkg.tasks)} tasks -> ${ok ? "ok" : "FAILED"}`);
  return ok;
}

// ---------------------------------------------------------------------- pack

/** One ustar header block; long paths use the 155-byte prefix field. */
function tarHeader(name, size, mtime) {
  const h = Buffer.alloc(512);
  let prefix = "";
  if (Buffer.byteLength(name) > 100) {
    const i = name.lastIndexOf("/", 155);
    prefix = name.slice(0, i);
    name = name.slice(i + 1);
  }
  if (Buffer.byteLength(name) > 100 || Buffer.byteLength(prefix) > 155) die(`${prefix}/${name}: path too long for tar`);
  const put = (s, off) => h.write(s, off, "utf8");
  const octal = (n, width) => Math.floor(n).toString(8).padStart(width - 1, "0") + "\0";
  put(name, 0);
  put(octal(0o644, 8), 100);
  put(octal(0, 8), 108);
  put(octal(0, 8), 116);
  put(octal(size, 12), 124);
  put(octal(mtime, 12), 136);
  put(" ".repeat(8), 148);
  put("0", 156);
  put("ustar\0", 257);
  put("00", 263);
  put(prefix, 345);
  let sum = 0;
  for (const b of h) sum += b;
  put(sum.toString(8).padStart(6, "0") + "\0 ", 148);
  return h;
}

function pack(pkg, out) {
  const files = pkg.files().filter((f) => pkg.rel(f) !== LOCK_FILE);
  const lock = {
    schema: SCHEMA, package: pkg.slug, version: pkg.company.version ?? null,
    files: Object.fromEntries(files.map((f) => [pkg.rel(f), crypto.createHash("sha256").update(fs.readFileSync(f)).digest("hex")])),
  };
  const lockBytes = Buffer.from(JSON.stringify(lock, null, 2) + "\n");
  fs.writeFileSync(path.join(pkg.root, LOCK_FILE), lockBytes);
  const prefix = `${pkg.slug}-${pkg.company.version ?? "0.0.0"}`;
  out = out || `${prefix}.tar.gz`;
  const blocks = [];
  const add = (name, data, mtime) => {
    blocks.push(tarHeader(name, data.length, mtime), data, Buffer.alloc((512 - (data.length % 512)) % 512));
  };
  for (const f of files) add(`${prefix}/${pkg.rel(f)}`, fs.readFileSync(f), fs.statSync(f).mtimeMs / 1000);
  add(`${prefix}/${LOCK_FILE}`, lockBytes, Date.now() / 1000);
  blocks.push(Buffer.alloc(1024));
  fs.writeFileSync(out, zlib.gzipSync(Buffer.concat(blocks)));
  console.log(`wrote ${out} (${files.length + 1} files) and ${LOCK_FILE}`);
}

// ------------------------------------------------------------- Multica target

class Api {
  constructor(base, token) {
    this.base = base.replace(/\/+$/, "");
    this.token = token;
    this.ws = null;
  }

  async call(method, p, body) {
    const headers = { "Content-Type": "application/json", Authorization: "Bearer " + this.token };
    if (this.ws) headers["X-Workspace-ID"] = this.ws;
    let r;
    try {
      r = await fetch(this.base + p, { method, headers, body: body === undefined ? undefined : JSON.stringify(body) });
    } catch (e) {
      die(`${method} ${p}: ${e.cause?.message || e.message}`);
    }
    const text = await r.text();
    if (!r.ok) die(`${method} ${p} -> ${r.status} ${text.slice(0, 500)}`);
    return text ? JSON.parse(text) : null;
  }

  async list(p, key) {
    let d = await this.call("GET", p);
    if (d && !Array.isArray(d)) d = key ? d[key] : Object.values(d).find(Array.isArray) || [];
    return d || [];
  }
}

class MulticaDeployer {
  constructor(pkg, api, dryRun, activateRoutines = false) {
    this.pkg = pkg;
    this.api = api;
    this.dry = dryRun;
    this.activate = activateRoutines;
    this.cfg = pkg.target("multica");
    this.changes = 0;
    this.ids = { agent: {}, squad: {}, skill: {}, workflow: {}, project: {}, autopilot: {} };
  }

  // -- bookkeeping
  log(op, kind, slug, extra = "") {
    if (op !== "=") this.changes += 1;
    console.log(`${op} ${kind.padEnd(9)} ${slug}${extra ? "  " + extra : ""}`);
  }

  statePath() {
    return path.join(this.pkg.root, ".opc", `multica-${this.wsSlug}.json`);
  }

  loadState() {
    const p = this.statePath();
    this.state = fs.existsSync(p) ? JSON.parse(fs.readFileSync(p, "utf8")) : {};
  }

  saveState() {
    if (this.dry) return;
    const p = this.statePath();
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(path.join(path.dirname(p), ".gitignore"), "*\n");
    const merged = {};
    for (const [kind, ids] of Object.entries(this.ids)) {
      merged[kind] = { ...(this.state[kind] || {}), ...Object.fromEntries(Object.entries(ids).filter(([, id]) => id)) };
    }
    fs.writeFileSync(p, JSON.stringify(merged, null, 2) + "\n");
  }

  /** Existing record for slug: by remembered id, else by name. */
  match(kind, slug, existing, name, nameKey = "name") {
    const sid = (this.state[kind] || {})[slug];
    return existing.find((x) => sid && x.id === sid) ?? existing.find((x) => x[nameKey] === name) ?? null;
  }

  /** Create or update one entity; returns its id (null for a create in a dry run). */
  async upsert(kind, slug, current, desired, create, update, compare = null) {
    let rid;
    if (current == null) {
      this.log("+", kind, slug);
      rid = this.dry ? null : (await create(desired)).id;
    } else {
      rid = current.id;
      const diff = (compare || Object.keys(desired)).filter((k) => !same(current[k], desired[k]));
      this.log(diff.length ? "~" : "=", kind, slug, diff.join(","));
      if (diff.length && !this.dry) await update(rid, desired);
    }
    this.ids[kind][slug] = rid;
    return rid;
  }

  // -- steps
  async run() {
    const { pkg, api } = this;
    this.wsSlug = this.cfg.workspace || pkg.slug;
    let ws = (await api.list("/api/workspaces")).find((w) => w.slug === this.wsSlug);
    if (!ws) {
      this.log("+", "workspace", this.wsSlug);
      if (this.dry) {
        console.log("(workspace does not exist yet; the rest of the plan assumes an empty workspace)");
        this.loadState();
        return this.planEmpty();
      }
      ws = await api.call("POST", "/api/workspaces", {
        name: pkg.company.name, slug: this.wsSlug, description: pkg.company.description,
        issue_prefix: this.cfg.issue_prefix || this.wsSlug.slice(0, 3).toUpperCase(),
      });
    } else {
      this.log("=", "workspace", this.wsSlug);
    }
    api.ws = ws.id;
    this.loadState();
    const me = await api.call("GET", "/api/me");
    this.me = me.id || me.user?.id;
    try {
      await this.skills();
      await this.agents();
      await this.squads();
      await this.statuses();
      await this.workflows();
      await this.projects();
      await this.routines();
    } finally {
      this.saveState();
    }
    console.log(`${this.dry ? "plan" : "deploy"}: ${this.changes} change(s) in workspace ${this.wsSlug}`);
  }

  planEmpty() {
    const { pkg } = this;
    const squads = Object.keys(pkg.teams).filter((s) => pkg.isSquad(s));
    const routines = Object.keys(pkg.tasks).filter((s) => pkg.tasks[s].meta.recurring);
    for (const [kind, slugs] of [["skill", Object.keys(pkg.skills)], ["agent", Object.keys(pkg.agents)],
      ["squad", squads], ["workflow", Object.keys(pkg.workflows)], ["project", Object.keys(pkg.projects)],
      ["autopilot", routines]]) {
      for (const slug of slugs) this.log("+", kind, slug);
    }
    console.log(`plan: ${this.changes} change(s)`);
  }

  async skills() {
    const existing = await this.api.list("/api/skills");
    for (const [slug, s] of Object.entries(this.pkg.skills)) {
      const dir = path.dirname(s.path);
      const files = walk(dir)
        .filter((f) => path.basename(f) !== "SKILL.md" && TEXT_SUFFIXES.has(path.extname(f)))
        .map((f) => ({ path: path.relative(dir, f).split(path.sep).join("/"), content: fs.readFileSync(f, "utf8") }));
      const byPath = (fs_) => fs_.map(({ path: p, content }) => ({ path: p, content })).sort((a, b) => a.path.localeCompare(b.path));
      // files is part of the diff, so a change to a script or reference alone is deployed too.
      const desired = { name: slug, description: s.meta.description || "", content: s.raw, files: byPath(files) };
      let cur = this.match("skill", slug, existing, slug);
      if (cur && !(has(cur, "content") && has(cur, "files"))) cur = await this.api.call("GET", `/api/skills/${cur.id}`);
      if (cur) cur = { ...cur, files: byPath(cur.files || []) };
      await this.upsert("skill", slug, cur, desired,
        (d) => this.api.call("POST", "/api/skills", d),
        (i, d) => this.api.call("PUT", `/api/skills/${i}`, d));
    }
  }

  runtimeFor(slug, cur) {
    const acfg = (this.cfg.agents || {})[slug] || {};
    const provider = acfg.provider || (this.cfg.defaults || {}).provider || "claude";
    // `runtime` picks one daemon when several serve the workspace: a substring of
    // the runtime's name or device, e.g. the --device-name the daemon was started with.
    const want = acfg.runtime ?? (this.cfg.defaults || {}).runtime;
    const rts = this.runtimes.filter((r) => r.provider === provider &&
      (!want || [r.name, r.custom_name, r.device_info].some((s) => (s || "").includes(want))));
    const online = rts.filter((r) => r.status === "online");
    const pick = online.length ? online : rts;
    if (!pick.length) {
      if (this.dry) return [null, acfg];
      die(`agent ${slug}: no ${q(provider)} runtime${want ? ` matching ${q(want)}` : ""} in this workspace; start the daemon first`);
    }
    // Never move an agent between daemons by accident: they can run as different users.
    if (cur && rts.some((r) => r.id === cur.runtime_id)) return [cur.runtime_id, acfg];
    if (pick.length > 1) {
      die(`agent ${slug}: ${pick.length} ${q(provider)} runtimes (${pick.map((r) => r.name).join(", ")}); ` +
        `set targets.multica.defaults.runtime or agents.${slug}.runtime in .fgopc.yaml`);
    }
    return [pick[0].id, acfg];
  }

  async agents() {
    this.runtimes = await this.api.list("/api/runtimes");
    const existing = await this.api.list("/api/agents");
    const defaults = this.cfg.defaults || {};
    for (const [slug, a] of Object.entries(this.pkg.agents)) {
      const m = a.meta;
      const cur = this.match("agent", slug, existing, m.name);
      const [runtimeId, acfg] = this.runtimeFor(slug, cur);
      const desired = {
        name: m.name,
        description: m.title || m.description || "",
        instructions: this.pkg.agentInstructions(slug),
        model: acfg.model ?? defaults.model ?? "",
        runtime_id: runtimeId,
        max_concurrent_tasks: acfg.max_concurrent_tasks ?? defaults.max_concurrent_tasks ?? 1,
      };
      // Only managed when the package sets it, so hand-made sharing is left alone.
      if (acfg.permission_mode) desired.permission_mode = acfg.permission_mode;
      const rid = await this.upsert("agent", slug, cur, desired,
        (d) => this.api.call("POST", "/api/agents", { ...d, visibility: d.permission_mode === "private" ? "private" : "workspace" }),
        (i, d) => this.api.call("PUT", `/api/agents/${i}`, d));
      const want = (m.skills || []).map((s) => this.ids.skill[s]).sort();
      const haveIds = ((cur || {}).skills || []).map((s) => s.id).sort();
      if (!same(want, haveIds)) {
        this.log("~", "skills", slug, (m.skills || []).join(",") || "(none)");
        if (!this.dry && rid) await this.api.call("PUT", `/api/agents/${rid}/skills`, { skill_ids: want });
      }
      await this.secrets(slug, rid);
    }
  }

  async secrets(slug, rid) {
    const env = {};
    for (const sec of this.pkg.ext.secrets || []) {
      if (!(sec.agents || []).includes(slug)) continue;
      const value = process.env[sec.env];
      if (value) env[sec.env] = value;
      else console.log(`! secret    ${slug}  ${sec.env} not set in the environment${sec.required ? " (required)" : ""}; left unchanged`);
    }
    const names = Object.keys(env).sort();
    if (names.length) {
      this.log("~", "secrets", slug, names.join(","));
      if (!this.dry && rid) await this.api.call("PUT", `/api/agents/${rid}/env`, { custom_env: env });
    }
  }

  async squads() {
    const existing = await this.api.list("/api/squads");
    for (const [slug, t] of Object.entries(this.pkg.teams)) {
      if (!this.pkg.isSquad(slug)) continue;
      const [manager, members] = this.pkg.teamMembers(slug);
      const desired = { name: t.meta.name || slug, description: t.meta.description || "", leader_id: this.ids.agent[manager] };
      const cur = this.match("squad", slug, existing, desired.name);
      const rid = await this.upsert("squad", slug, cur, desired,
        (d) => this.api.call("POST", "/api/squads", d),
        (i, d) => this.api.call("PUT", `/api/squads/${i}`, d));
      const have = new Map();
      if (rid && cur) for (const m of await this.api.list(`/api/squads/${rid}/members`)) have.set(m.member_id, m);
      for (const mslug of members) {
        const aid = this.ids.agent[mslug];
        const role = this.pkg.agents[mslug].meta.title || "";
        if (!aid || !have.has(aid)) {
          this.log("+", "member", `${slug}/${mslug}`);
          if (!this.dry && rid) await this.api.call("POST", `/api/squads/${rid}/members`, { member_type: "agent", member_id: aid, role });
        } else if (have.get(aid).role !== role) {
          this.log("~", "member", `${slug}/${mslug}`, "role");
          if (!this.dry) await this.api.call("PATCH", `/api/squads/${rid}/members/role`, { member_type: "agent", member_id: aid, role });
        }
      }
      const wanted = new Set([...members.map((m) => this.ids.agent[m]), desired.leader_id]);
      for (const [aid, mem] of have) {
        if (wanted.has(aid)) continue;
        this.log("-", "member", `${slug}/${aid.slice(0, 8)}`);
        if (!this.dry) await this.api.call("DELETE", `/api/squads/${rid}/members`, { member_type: mem.member_type || "agent", member_id: aid });
      }
    }
  }

  async statuses() {
    const have = new Set((await this.api.list("/api/issue-statuses", "statuses")).map((s) => s.key));
    for (const w of Object.values(this.pkg.workflows)) {
      for (const s of w.meta.statuses || []) {
        if (have.has(s.key) || BUILTIN_STATUSES.has(s.key)) continue;
        have.add(s.key);
        this.log("+", "status", s.key);
        if (!this.dry) {
          await this.api.call("POST", "/api/issue-statuses", { key: s.key, name: s.name, category: s.category, color: s.color || "#8b5cf6" });
        }
      }
    }
  }

  handler(h) {
    if (!h) return { type: "none" };
    if (has(h, "agent")) return { type: "agent", id: this.ids.agent[h.agent] };
    if (has(h, "team")) {
      // Multica rejects squad handoffs (a squad routes its own work), so a
      // team step goes to its manager, whose instructions delegate by @mention.
      return { type: "agent", id: this.ids.agent[this.pkg.teamMembers(h.team)[0]] };
    }
    if (h.role === "owner" || h.member === "me") return { type: "member", id: this.me };
    if (h.role === "project_lead") return { type: "project_lead" };
    die(`unsupported handler ${JSON.stringify(h)}`);
  }

  static ruleText(rules) {
    const out = [];
    if ((rules || {}).done_requires === "human") out.push("Không tự chuyển issue sang done; chỉ người mới được đóng issue.");
    if ((rules || {}).max_send_backs) out.push(`Nếu issue đã bị trả lại ${rules.max_send_backs} lần, dừng lại và hỏi chủ trong comment.`);
    return out.join(" ");
  }

  async workflows() {
    const existing = await this.api.list("/api/issue-workflows");
    for (const [slug, w] of Object.entries(this.pkg.workflows)) {
      const m = w.meta;
      const rules = MulticaDeployer.ruleText(m.rules);
      const steps = m.statuses.map((s) => {
        const h = this.handler(s.handler);
        let instr = (s.instructions || "").trim();
        if (rules && h.type === "agent") instr = `${instr}\n${rules}`.trim();
        return { status_key: s.key, handler: h, instructions: instr, next_status_key: s.next || "", back_status_key: s.back || "" };
      });
      const desired = { name: m.name || slug, description: [...(m.description || "")].slice(0, 256).join(""), steps };
      let cur = this.match("workflow", slug, existing, desired.name);
      if (cur) cur = { ...cur, steps: MulticaDeployer.normalizeSteps(cur.steps || [], new Set(steps.map((s) => s.status_key))) };
      await this.upsert("workflow", slug, cur, desired,
        (d) => this.api.call("POST", "/api/issue-workflows", d),
        (i, d) => this.api.call("PATCH", `/api/issue-workflows/${i}`, d));
    }
  }

  /** Server steps in the request shape; drops fixed statuses Multica adds itself. */
  static normalizeSteps(steps, wantedKeys) {
    return steps
      .filter((s) => !(s.status_key === "cancelled" && !wantedKeys.has(s.status_key)))
      .map((s) => {
        const h = s.handler || { type: "none" };
        return {
          status_key: s.status_key,
          handler: Object.fromEntries(Object.entries(h).filter(([k, v]) => ["type", "id"].includes(k) && v)),
          instructions: s.instructions || "",
          next_status_key: s.next_status_key || "",
          back_status_key: s.back_status_key || "",
        };
      });
  }

  async projects() {
    const existing = await this.api.list("/api/projects");
    const bindings = this.pkg.ext.projects || {};
    for (const [slug, p] of Object.entries(this.pkg.projects)) {
      const m = p.meta;
      const desired = { title: m.name || slug, description: m.description || [...p.body.trim()].slice(0, 2000).join("") };
      if (m.owner) Object.assign(desired, { lead_type: "agent", lead_id: this.ids.agent[m.owner] });
      const cur = this.match("project", slug, existing, desired.title, "title");
      const rid = await this.upsert("project", slug, cur, desired,
        (d) => this.api.call("POST", "/api/projects", d),
        (i, d) => this.api.call("PUT", `/api/projects/${i}`, d));
      const wf = (bindings[slug] || {}).workflow;
      if (!wf) continue;
      const wid = this.ids.workflow[wf];
      if (!cur || cur.workflow_id !== wid || !wid) {
        this.log("~", "binding", `${slug} -> ${wf}`);
        if (!this.dry && rid) await this.api.call("POST", `/api/projects/${rid}/workflow`, { workflow_id: wid });
      }
    }
  }

  async routines() {
    const { pkg } = this;
    const existing = await this.api.list("/api/autopilots");
    const rcfg = pkg.ext.routines || {};
    for (const [slug, t] of Object.entries(pkg.tasks)) {
      const m = t.meta;
      if (!m.recurring) continue;
      const who = m.assignee;
      let atype, aid;
      if (has(pkg.teams, who) && pkg.isSquad(who)) {
        [atype, aid] = ["squad", this.ids.squad[who]];
      } else {
        const aslug = has(pkg.teams, who) ? pkg.teamMembers(who)[0] : who;
        [atype, aid] = ["agent", this.ids.agent[aslug]];
      }
      const desired = {
        title: m.name || slug, description: t.body.trim(), project_id: this.ids.project[m.project],
        assignee_type: atype, assignee_id: aid, execution_mode: "create_issue",
      };
      const cur = this.match("autopilot", slug, existing, desired.title, "title");
      const rid = await this.upsert("autopilot", slug, cur, desired,
        (d) => this.api.call("POST", "/api/autopilots", d),
        (i, d) => this.api.call("PATCH", `/api/autopilots/${i}`, d),
        ["title", "description", "project_id", "assignee_type", "assignee_id"]);
      if (!cur && !this.dry && rid && !this.activate) {
        await this.api.call("PATCH", `/api/autopilots/${rid}`, { status: "paused" });
        console.log(`  autopilot ${slug} created paused; enable it in Multica or deploy with --activate-routines`);
      }
      const have = !cur || !rid ? [] : ((await this.api.call("GET", `/api/autopilots/${rid}`)).triggers || []);
      for (const trig of (rcfg[slug] || {}).triggers || []) {
        const cron = trig.cron, tz = trig.timezone || "Asia/Ho_Chi_Minh";
        if (have.some((h) => h.cron_expression === cron)) continue;
        this.log("+", "trigger", `${slug} ${cron} ${tz}`);
        if (!this.dry && rid) {
          await this.api.call("POST", `/api/autopilots/${rid}/triggers`, { kind: "schedule", cron_expression: cron, timezone: tz });
        }
      }
    }
  }
}

function multicaApi() {
  const home = (process.env.MULTICA_HOME || "~/multica-spike").replace(/^~(?=$|\/)/, os.homedir());
  const tokenFile = process.env.MULTICA_TOKEN_FILE || path.join(home, ".pat");
  if (!fs.existsSync(tokenFile)) die(`${tokenFile}: no token; run multica/stack/bootstrap.py first`);
  return new Api(process.env.MULTICA_API || "http://127.0.0.1:8310", fs.readFileSync(tokenFile, "utf8").trim());
}

