//     opc.mjs deploy <package> [--activate-routines]
//
// Deploy is idempotent: entities are matched by slug through a state file
// (<package>/.opc/multica-<workspace>.json), falling back to name. Secret values
// come from environment variables named in .fgopc.yaml and are never printed.

input.new_string:
//     opc.mjs deploy <package> [--activate-routines]
//     opc.mjs tools  <package> [--prefix /opt/opc-agent] [--check]
//
// Deploy is idempotent: entities are matched by slug through a state file
// (<package>/.opc/multica-<workspace>.json), falling back to name. Secret values
// come from environment variables named in .fgopc.yaml and are never printed.
//
// Tools installs the pinned MCP server packages of .fgopc.yaml `mcp` under a
// prefix on the daemon host (default /opt/opc-agent, whose bin/ is on the agent
// daemon's PATH); --check starts each server and lists its tools over stdio.

import zlib from "node:zlib";
import { spawn, spawnSync } from "node:child_process";
import { parseArgs, isDeepStrictEqual } from "node:util";

const LOCK_FILE = "company-package.lock.json";
const MCP_NAME = /^[A-Za-z0-9_-]+$/; // Multica's rule for workspace MCP server names
const EXACT_VERSION = /^\d+\.\d+\.\d+([.+-][0-9A-Za-z.-]+)?$/;
const UV_VERSION = "0.12.24"; // installs the pypi MCP servers; fetched with its published sha256
const DEFAULT_PREFIX = "/opt/opc-agent";

input.old_string:
  rel(file) {
    return path.relative(this.root, file).split(path.sep).join("/");
  }
}

input.new_string:
  rel(file) {
    return path.relative(this.root, file).split(path.sep).join("/");
  }

  get mcp() {
    return this.ext.mcp || {};
  }
}

/**
 * The `mcpServers` entry for one server, with ${VAR} / ${VAR:-default} taken
 * from env; an env key whose value ends up empty is left out. Returns
 * [config, names of required variables that are unset].
 */
function renderMcp(spec, env = process.env) {
  const missing = [];
  const fill = (s) => String(s).replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)(:-([^}]*))?\}/g, (_, name, dflt, value) => {
    if (env[name]) return env[name];
    if (dflt === undefined) missing.push(name);
    return value ?? "";
  });
  const config = { command: spec.command, args: (spec.args || []).map(fill) };
  const vars = Object.entries(spec.env || {}).map(([k, v]) => [k, fill(v)]).filter(([, v]) => v);
  if (vars.length) config.env = Object.fromEntries(vars);
  return [config, missing];
}

