  if (pm && !["private", "public_to"].includes(pm)) E.push(`.fgopc.yaml targets.multica.agents.${slug}: permission_mode must be private or public_to`);
}

input.new_string:
  const pm = (acfg || {}).permission_mode;
  if (pm && !["private", "public_to"].includes(pm)) E.push(`.fgopc.yaml targets.multica.agents.${slug}: permission_mode must be private or public_to`);
}

for (const [name, spec] of Object.entries(pkg.mcp)) {
  const at = `.fgopc.yaml mcp.${name}`;
  if (!MCP_NAME.test(name)) E.push(`${at}: name may only contain letters, digits, '-' and '_'`);
  if (!spec || typeof spec.command !== "string" || !spec.command) { E.push(`${at}: needs a command`); continue; }
  if (spec.args && !Array.isArray(spec.args)) E.push(`${at}: args must be a list`);
  for (const [k, v] of Object.entries(spec.env || {})) {
    if (typeof v !== "string") E.push(`${at}.env.${k}: must be a string`);
    else if (!/^\$\{[^}]+\}$/.test(v.trim()) && SECRET_PATTERNS.some((p) => p.test(v))) E.push(`${at}.env.${k}: put secrets in the deploy environment as \${VAR}`);
  }
  for (const a of spec.agents || []) {
    if (!has(pkg.agents, a)) E.push(`${at}: agent ${q(a)} not found`);
  }
  if (!(spec.agents || []).length) W.push(`${at}: given to no agent`);
  const inst = spec.install;
  if (!inst) {
    W.push(`${at}: no install; ${q(spec.command)} must already be on the daemon's PATH`);
  } else {
    const kinds = ["npm", "pypi"].filter((k) => has(inst, k));
    if (kinds.length !== 1) E.push(`${at}.install: exactly one of npm, pypi`);
    if (!EXACT_VERSION.test(String(inst.version ?? ""))) E.push(`${at}.install: version must be exact (e.g. 1.2.3), not a range`);
    if (path.basename(spec.command) !== spec.command) E.push(`${at}: an installed server's command is the package's bin name, not a path`);
  }
}

