// --------------------------------------------------------------------- tools

/** Run a command, streaming its output; dies on a non-zero exit. */
function run(cmd, args, env = {}) {
  console.log(`$ ${cmd} ${args.join(" ")}`);
  const r = spawnSync(cmd, args, { stdio: "inherit", env: { ...process.env, ...env } });
  if (r.error) die(`${cmd}: ${r.error.message}`);
  if (r.status !== 0) die(`${cmd} exited with ${r.status}`);
}

/** cmd from <prefix>/bin if it is there, else from PATH. */
function which(cmd, prefix) {
  const own = path.join(prefix, "bin", cmd);
  if (fs.existsSync(own)) return own;
  for (const dir of (process.env.PATH || "").split(path.delimiter)) {
    if (dir && fs.existsSync(path.join(dir, cmd))) return path.join(dir, cmd);
  }
  return null;
}

/** uv at UV_VERSION in <prefix>/lib/uv, from the GitHub release, checked against its sha256. */
async function ensureUv(prefix) {
  const dir = path.join(prefix, "lib", `uv-${UV_VERSION}`), uv = path.join(dir, "uv");
  if (fs.existsSync(uv)) return uv;
  const asset = `uv-${os.arch() === "arm64" ? "aarch64" : "x86_64"}-unknown-linux-gnu.tar.gz`;
  const url = `https://github.com/astral-sh/uv/releases/download/${UV_VERSION}/${asset}`;
  console.log(`fetch ${url}`);
  const get = async (u) => {
    const r = await fetch(u);
    if (!r.ok) die(`GET ${u} -> ${r.status}`);
    return Buffer.from(await r.arrayBuffer());
  };
  const [tgz, sum] = await Promise.all([get(url), get(url + ".sha256")]);
  const want = sum.toString().trim().split(/\s+/)[0];
  const got = crypto.createHash("sha256").update(tgz).digest("hex");
  if (got !== want) die(`${asset}: sha256 ${got}, release says ${want}`);
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "opc-uv-"));
  try {
    fs.writeFileSync(path.join(tmp, asset), tgz);
    fs.mkdirSync(dir, { recursive: true });
    run("tar", ["-xzf", path.join(tmp, asset), "-C", dir, "--strip-components=1"]);
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
  return uv;
}

/**
 * Install every pinned MCP server under prefix: npm packages each in
 * <prefix>/lib/mcp/<name>, pypi packages as uv tools with a uv-managed Python,
 * both exposing their command in <prefix>/bin. Idempotent.
 */
async function installTools(pkg, prefix) {
  process.umask(0o022); // the daemon runs as another user; it must read what root installs
  const bin = path.join(prefix, "bin");
  fs.mkdirSync(bin, { recursive: true });
  let uv = null;
  for (const [name, spec] of Object.entries(pkg.mcp)) {
    const inst = spec.install;
    if (!inst) { console.log(`= tool      ${name}  no install; uses ${spec.command} from PATH`); continue; }
    if (inst.npm) {
      const npm = which("npm", prefix) || die("npm not found; install Node first (stack/agent-user.sh setup)");
      const dir = path.join(prefix, "lib", "mcp", name);
      fs.mkdirSync(dir, { recursive: true });
      run(npm, ["install", "--prefix", dir, "--save-exact", "--omit=dev", "--no-audit", "--no-fund", `${inst.npm}@${inst.version}`]);
      const target = path.join(dir, "node_modules", ".bin", spec.command);
      if (!fs.existsSync(target)) die(`mcp.${name}: ${inst.npm}@${inst.version} has no bin ${q(spec.command)}`);
      fs.rmSync(path.join(bin, spec.command), { force: true });
      fs.symlinkSync(target, path.join(bin, spec.command));
    } else {
      uv ??= await ensureUv(prefix);
      const lib = path.join(prefix, "lib");
      run(uv, ["tool", "install", "--python", String(inst.python || "3.12"), `${inst.pypi}==${inst.version}`], {
        UV_TOOL_DIR: path.join(lib, "uv-tools"), UV_TOOL_BIN_DIR: bin,
        UV_PYTHON_INSTALL_DIR: path.join(lib, "python"), UV_PYTHON_PREFERENCE: "only-managed",
        UV_CACHE_DIR: path.join(lib, "uv-cache"), UV_NO_CONFIG: "1",
      });
      if (!fs.existsSync(path.join(bin, spec.command))) die(`mcp.${name}: ${inst.pypi}==${inst.version} has no command ${q(spec.command)}`);
    }
    console.log(`+ tool      ${name}  ${path.join(bin, spec.command)}`);
  }
}

/** Start one stdio MCP server, initialize, list its tools; resolves to the tool names. */
function mcpToolNames(command, config, prefix, timeoutMs = 60000) {
  return new Promise((resolve, reject) => {
    const env = { ...process.env, ...(config.env || {}), PATH: `${path.join(prefix, "bin")}${path.delimiter}${process.env.PATH}` };
    const child = spawn(command, config.args || [], { env, stdio: ["pipe", "pipe", "pipe"] });
    let out = "", err = "";
    const timer = setTimeout(() => { child.kill(); reject(new Error(`no answer in ${timeoutMs / 1000}s; stderr: ${err.slice(-300)}`)); }, timeoutMs);
    const send = (m) => child.stdin.write(JSON.stringify({ jsonrpc: "2.0", ...m }) + "\n");
    child.on("error", (e) => { clearTimeout(timer); reject(e); });
    child.on("exit", (code) => { clearTimeout(timer); reject(new Error(`exited with ${code}; stderr: ${err.slice(-300)}`)); });
    child.stderr.on("data", (d) => { err += d; });
    child.stdout.on("data", (d) => {
      out += d;
      let i;
      while ((i = out.indexOf("\n")) !== -1) {
        const line = out.slice(0, i).trim();
        out = out.slice(i + 1);
        let msg;
        try { msg = JSON.parse(line); } catch { continue; }
        if (msg.id === 1) {
          send({ method: "notifications/initialized" });
          send({ id: 2, method: "tools/list", params: {} });
        } else if (msg.id === 2) {
          clearTimeout(timer);
          child.removeAllListeners("exit");
          child.kill();
          if (msg.error) reject(new Error(msg.error.message));
          else resolve((msg.result?.tools || []).map((t) => t.name));
        }
      }
    });
    send({ id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "opc", version: "0" } } });
  });
}

async function checkTools(pkg, prefix) {
  let ok = true;
  for (const [name, spec] of Object.entries(pkg.mcp)) {
    const [config, missing] = renderMcp(spec);
    const command = which(spec.command, prefix);
    if (!command) { console.log(`! tool      ${name}  ${spec.command} not installed`); ok = false; continue; }
    try {
      const tools = await mcpToolNames(command, config, prefix);
      console.log(`= tool      ${name}  ${tools.length} tools: ${tools.join(", ")}`);
      if (missing.length) console.log(`  (started without ${missing.join(", ")}; calls will fail until deploy sets them)`);
    } catch (e) {
      console.log(`! tool      ${name}  ${e.message}`);
      ok = false;
    }
  }
  return ok;
}

