import { spawn } from "node:child_process";
const [cmd, tool, args] = [process.argv[2], process.argv[3], JSON.parse(process.argv[4])];
const c = spawn(cmd, [], { stdio: ["pipe", "pipe", "inherit"] });
const send = (m) => c.stdin.write(JSON.stringify({ jsonrpc: "2.0", ...m }) + "\n");
let buf = "";
c.stdout.on("data", (d) => { buf += d; let i; while ((i = buf.indexOf("\n")) >= 0) { const l = buf.slice(0, i); buf = buf.slice(i + 1); let m; try { m = JSON.parse(l); } catch { continue; }
  if (m.id === 1) { send({ method: "notifications/initialized" }); send({ id: 2, method: "tools/call", params: { name: tool, arguments: args } }); }
  else if (m.id === 2) { console.log((m.result?.content || []).map((x) => x.text).join("\n").slice(0, 1500) || JSON.stringify(m)); c.kill(); } } });
send({ id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "t", version: "0" } } });
setTimeout(() => { console.log("timeout"); c.kill(); }, 90000);
EOF
