200	/**
201	 * The `mcpServers` entry for one server, with ${VAR} / ${VAR:-default} taken
202	 * from env; an env key whose value ends up empty is left out. An installed
203	 * server runs from <prefix>/bin by absolute path, so it does not depend on the
204	 * daemon's PATH. Returns [config, names of required variables that are unset].
205	 */
206	function renderMcp(spec, prefix = DEFAULT_PREFIX, env = process.env) {
207	  const missing = [];
208	  const fill = (s) => String(s).replace(/\$\{([A-Za-z_][A-Za-z0-9_]*)(:-([^}]*))?\}/g, (_, name, dflt, value) => {
209	    if (env[name]) return env[name];
210	    if (dflt === undefined) missing.push(name);
211	    return value ?? "";
212	  });
213	  const command = spec.install ? path.join(prefix, "bin", spec.command) : spec.command;
214	  const config = { command, args: (spec.args || []).map(fill) };
215	  const vars = Object.entries(spec.env || {}).map(([k, v]) => [k, fill(v)]).filter(([, v]) => v);
216	  if (vars.length) config.env = Object.fromEntries(vars);
217	  return [config, missing];
218	}
