902	/**
903	 * Install every pinned MCP server under prefix: npm packages each in
904	 * <prefix>/lib/mcp/<name>, pypi packages as uv tools with a uv-managed Python,
905	 * both exposing their command in <prefix>/bin. Idempotent.
906	 */
907	async function installTools(pkg, prefix) {
908	  process.umask(0o022); // the daemon runs as another user; it must read what root installs
909	  const bin = path.join(prefix, "bin");
910	  fs.mkdirSync(bin, { recursive: true });
911	  let uv = null;
912	  for (const [name, spec] of Object.entries(pkg.mcp)) {
913	    const inst = spec.install;
914	    if (!inst) { console.log(`= tool      ${name}  no install; uses ${spec.command} from PATH`); continue; }
915	    if (inst.npm) {
916	      const npm = which("npm", prefix) || die("npm not found; install Node first (stack/agent-user.sh setup)");
917	      const dir = path.join(prefix, "lib", "mcp", name);
918	      fs.mkdirSync(dir, { recursive: true });
919	      run(npm, ["install", "--prefix", dir, "--save-exact", "--omit=dev", "--no-audit", "--no-fund", `${inst.npm}@${inst.version}`]);
920	      const target = path.join(dir, "node_modules", ".bin", spec.command);
921	      if (!fs.existsSync(target)) die(`mcp.${name}: ${inst.npm}@${inst.version} has no bin ${q(spec.command)}`);
922	      // A wrapper, not a symlink: the bin's `#!/usr/bin/env node` would need node on the daemon's PATH.
923	      const node = which("node", prefix);
924	      fs.rmSync(path.join(bin, spec.command), { force: true });
925	      fs.writeFileSync(path.join(bin, spec.command), `#!/bin/sh\nexec "${node}" "${fs.realpathSync(target)}" "$@"\n`, { mode: 0o755 });
926	    } else {
927	      uv ??= await ensureUv(prefix);
928	      const lib = path.join(prefix, "lib");
929	      run(uv, ["tool", "install", "--python", String(inst.python || "3.12"), `${inst.pypi}==${inst.version}`], {
930	        UV_TOOL_DIR: path.join(lib, "uv-tools"), UV_TOOL_BIN_DIR: bin,
931	        UV_PYTHON_INSTALL_DIR: path.join(lib, "python"), UV_PYTHON_PREFERENCE: "only-managed",
932	        UV_CACHE_DIR: path.join(lib, "uv-cache"), UV_NO_CONFIG: "1",
933	      });
934	      if (!fs.existsSync(path.join(bin, spec.command))) die(`mcp.${name}: ${inst.pypi}==${inst.version} has no command ${q(spec.command)}`);
935	    }
936	    console.log(`+ tool      ${name}  ${path.join(bin, spec.command)}`);
937	  }
938	}
