940	/** Start one stdio MCP server, initialize, list its tools; resolves to the tool names. */
941	function mcpToolNames(command, config, prefix, timeoutMs = 60000) {
942	  return new Promise((resolve, reject) => {
943	    const env = { ...process.env, ...(config.env || {}), PATH: `${path.join(prefix, "bin")}${path.delimiter}${process.env.PATH}` };
944	    const child = spawn(command, config.args || [], { env, stdio: ["pipe", "pipe", "pipe"] });
945	    let out = "", err = "";
946	    const timer = setTimeout(() => { child.kill(); reject(new Error(`no answer in ${timeoutMs / 1000}s; stderr: ${err.slice(-300)}`)); }, timeoutMs);
947	    const send = (m) => child.stdin.write(JSON.stringify({ jsonrpc: "2.0", ...m }) + "\n");
948	    child.on("error", (e) => { clearTimeout(timer); reject(e); });
949	    child.on("exit", (code) => { clearTimeout(timer); reject(new Error(`exited with ${code}; stderr: ${err.slice(-300)}`)); });
950	    child.stderr.on("data", (d) => { err += d; });
951	    child.stdout.on("data", (d) => {
952	      out += d;
953	      let i;
954	      while ((i = out.indexOf("\n")) !== -1) {
955	        const line = out.slice(0, i).trim();
956	        out = out.slice(i + 1);
957	        let msg;
958	        try { msg = JSON.parse(line); } catch { continue; }
959	        if (msg.id === 1) {
960	          send({ method: "notifications/initialized" });
961	          send({ id: 2, method: "tools/list", params: {} });
962	        } else if (msg.id === 2) {
963	          clearTimeout(timer);
964	          child.removeAllListeners("exit");
965	          child.kill();
966	          if (msg.error) reject(new Error(msg.error.message));
967	          else resolve((msg.result?.tools || []).map((t) => t.name));
968	        }
969	      }
970	    });
971	    send({ id: 1, method: "initialize", params: { protocolVersion: "2025-06-18", capabilities: {}, clientInfo: { name: "opc", version: "0" } } });
972	  });
973	}
