978	    const [config, missing] = renderMcp(spec, prefix);
979	    const command = spec.install ? config.command : which(spec.command, prefix);
980	    if (!command || !fs.existsSync(command)) { console.log(`! tool      ${name}  ${spec.command} not installed`); ok = false; continue; }
981	    try {
982	      const tools = await mcpToolNames(command, config, prefix);
983	      console.log(`= tool      ${name}  ${tools.length} tools: ${tools.join(", ")}`);
984	      if (missing.length) console.log(`  (started without ${missing.join(", ")}; calls will fail until deploy sets them)`);
985	    } catch (e) {
986	      console.log(`! tool      ${name}  ${e.message}`);
987	      if (missing.length) console.log(`  (set ${missing.join(", ")} as deploy will, then run --check again)`);
988	      ok = false;
