"""    const want = acfg.runtime ?? process.env.OPC_RUNTIME ?? (this.cfg.defaults || {}).runtime;""")
rep("""function multicaApi() {""","""// -------------------------------------------------------------------- client

const PACKAGES_DIR = path.resolve(path.dirname(new URL(import.meta.url).pathname), "..", "packages");

/** <dir>/client.yaml, validated; secret paths resolved next to it and checked for mode 600. */
function loadClient(dir) {
  dir = path.resolve(dir);
  const file = path.join(dir, "client.yaml");
  if (!fs.existsSync(file)) die(`${file}: no client manifest (see playbook/client.example.yaml)`);
  const c = parseYaml(fs.readFileSync(file, "utf8"), file) || {};
  const ws = c.workspace || {};
  if (!/^[a-z0-9][a-z0-9-]*$/.test(ws.slug || "")) die(`${file}: workspace.slug must be lowercase letters, digits and '-'`);
  if (!ws.name) die(`${file}: workspace.name is required`);
  if (!Array.isArray(c.sets) || !c.sets.length) die(`${file}: sets lists the packages this client bought`);
  const secrets = {};
  for (const [name, rel] of Object.entries(c.secrets || {})) {
    const abs = path.resolve(dir, String(rel).replace(/^~(?=$|\\/)/, os.homedir()));
    if (!fs.existsSync(abs)) die(`${file}: secrets.${name}: ${abs} does not exist`);
    if (fs.statSync(abs).mode & 0o077) die(`${abs}: readable by others; chmod 600 it`);
    secrets[name] = abs;
  }
  const sets = c.sets.map((s) => {
    const root = path.isAbsolute(s) ? s : path.join(PACKAGES_DIR, s);
    if (!fs.existsSync(path.join(root, "COMPANY.md"))) die(`${file}: set ${q(s)} is not a package under ${PACKAGES_DIR}`);
    return root;
  });
  return { dir, file, ws, members: c.members || [], runtime: c.runtime, vars: c.vars || {}, secrets, sets };
}

/** The client's values as environment, over whatever the shell had: the manifest is the source of truth. */
function applyClient(c) {
  const env = { OPC_WORKSPACE: c.ws.slug, OPC_WORKSPACE_NAME: c.ws.name, ...c.vars, ...c.secrets };
  if (c.ws.issue_prefix) env.OPC_ISSUE_PREFIX = c.ws.issue_prefix;
  if (c.runtime) env.OPC_RUNTIME = c.runtime;
  for (const [k, v] of Object.entries(env)) process.env[k] = String(v);
}

/** What two sets in one workspace must not both define, or define differently. */
function checkSets(pkgs) {
  const E = [];
  const seen = {};
  const claim = (kind, key, pkg) => {
    const k = `${kind}:${key}`;
    if (seen[k] && seen[k] !== pkg.slug) E.push(`${kind} ${q(key)} is in both ${seen[k]} and ${pkg.slug}`);
    else seen[k] = pkg.slug;
  };
  const statuses = {};
  for (const pkg of pkgs) {
    for (const [slug, a] of Object.entries(pkg.agents)) { claim("agent", slug, pkg); claim("agent name", a.meta.name, pkg); }
    for (const slug of Object.keys(pkg.skills)) claim("skill", slug, pkg);
    for (const [slug, tm] of Object.entries(pkg.teams)) { claim("team", slug, pkg); claim("squad name", tm.meta.name || slug, pkg); }
    for (const [slug, p] of Object.entries(pkg.projects)) { claim("project", slug, pkg); claim("project name", p.meta.name || slug, pkg); }
    for (const [slug, w] of Object.entries(pkg.workflows)) { claim("workflow", slug, pkg); claim("workflow name", w.meta.name || slug, pkg); }
    for (const [slug, tk] of Object.entries(pkg.tasks)) { claim("task", slug, pkg); claim("routine name", tk.meta.name || slug, pkg); }
    for (const name of Object.keys(pkg.mcp)) claim("MCP server", name, pkg);
    // Statuses belong to the workspace: a key two sets share must mean the same column.
    for (const w of Object.values(pkg.workflows)) {
      for (const s of w.meta.statuses || []) {
        if (BUILTIN_STATUSES.has(s.key)) continue;
        const def = { name: s.name, category: s.category }, prev = statuses[s.key];
        if (prev && !same(prev.def, def) && prev.pkg !== pkg.slug) E.push(`status ${q(s.key)}: ${prev.pkg} and ${pkg.slug} define it differently`);
        statuses[s.key] ??= { def, pkg: pkg.slug };
      }
    }
  }
  return E;
}

/** Invite the client's people (role member unless given as {email, role}). */
async function clientMembers(api, c, dry) {
  if (!c.members.length) return 0;
  const ws = (await api.list("/api/workspaces")).find((w) => w.slug === c.ws.slug);
  if (!ws) { for (const m of c.members) console.log(`+ member    ${m.email || m} (invite)`); return c.members.length; }
  const have = new Set([
    ...(await api.list(`/api/workspaces/${ws.id}/members`)).map((m) => (m.email || m.user?.email || "").toLowerCase()),
    ...(await api.list(`/api/workspaces/${ws.id}/invitations`)).map((i) => (i.email || i.invitee_email || "").toLowerCase()),
  ]);
  let n = 0;
  for (const m of c.members) {
    const email = String(m.email || m).toLowerCase(), role = m.role || "member";
    if (have.has(email)) continue;
    console.log(`+ member    ${email} (invite, ${role})`);
    n += 1;
    if (!dry) await api.call("POST", `/api/workspaces/${ws.id}/members`, { email, role });
  }
  return n;
}

async function client(sub, dir, opts) {
  const c = loadClient(dir);
  applyClient(c);
  console.log(`client ${c.ws.slug} (${c.ws.name}): ${c.sets.map((s) => path.basename(s)).join(", ")}`);
  const pkgs = c.sets.map((s) => new Package(s));
  let ok = true;
  for (const pkg of pkgs) ok = printLint(pkg) && ok;
  const conflicts = checkSets(pkgs);
  for (const e of conflicts) console.log("error:", e);
  if (!ok || conflicts.length) die("fix the errors first");
  for (const pkg of pkgs) {
    const unset = pkg.templateVars().filter((v) => !process.env[v]);
    if (unset.length) die(`${pkg.slug} needs ${unset.join(", ")}: add them to vars in ${c.file}`);
  }
  if (sub === "tools") {
    let good = true;
    for (const pkg of pkgs) {
      if (!Object.keys(pkg.mcp).length && !Object.keys(pkg.secretFiles).length) continue;
      console.log(`--- ${pkg.slug}`);
      const host = hostOf(pkg, opts);
      if (!opts.check) await installTools(pkg, host);
      good = (await checkTools(pkg, host)) && good;
    }
    process.exit(good ? 0 : 1);
  }
  const api = multicaApi();
  const dry = sub === "plan";
  for (const pkg of pkgs) {
    console.log(`--- ${pkg.slug}`);
    await new MulticaDeployer(pkg, api, dry, opts["activate-routines"], hostOf(pkg, opts)).run();
  }
  console.log("--- members");
  console.log(`${dry ? "plan" : "deploy"}: ${await clientMembers(api, c, dry)} invitation(s)`);
}

function multicaApi() {""")
rep("""       opc.mjs tools  <package> [--env client.env] [--user U] [--prefix DIR] [--check]   # as root
""","""       opc.mjs tools  <package> [--env client.env] [--user U] [--prefix DIR] [--check]   # as root
