 * Where the package runs: the daemon's Linux user (and its home) and the tool
 * prefix, from .fgopc.yaml `host` unless --user / --prefix say otherwise.
 */
function hostOf(pkg, opts = {}) {
  const h = pkg.ext.host || {};
  const user = opts.user || h.user || os.userInfo().username;
  const r = spawnSync("getent", ["passwd", user], { encoding: "utf8" });
  const f = (r.stdout || "").trim().split(":");
  if (f.length < 6) die(`host user ${q(user)} does not exist on this machine`);
  return { user, uid: Number(f[2]), gid: Number(f[3]), home: f[5], prefix: path.resolve(opts.prefix || h.prefix || DEFAULT_PREFIX) };
}

/** ${VAR}, ${VAR:-default} and ${file:<name>} (a `files` entry's path on the host). */
function filler(pkg, host, env, missing) {
  const fill = (s) => String(s).replace(/\$\{(file:)?([A-Za-z_][A-Za-z0-9_-]*)(:-([^}]*))?\}/g, (m, file, name, dflt, value) => {
    if (file) {
      const f = pkg.secretFiles[name] || die(`\${file:${name}}: no files.${name} in .fgopc.yaml`);
      return path.join(host.home, fill(f.to));
    }
    if (env[name]) return env[name];
    if (dflt === undefined) missing.push(name);
    return value ?? "";
  });
  return fill;
}

/**
 * The `mcpServers` entry for one server; an env key whose value ends up empty
 * is left out. An installed server runs from <prefix>/bin by absolute path, so
 * it does not depend on the daemon's PATH. Returns [config, unset required vars].
 */
function renderMcp(pkg, spec, host, env = process.env) {
  const missing = [];
  const fill = filler(pkg, host, env, missing);
  const command = spec.install ? path.join(host.prefix, "bin", spec.command) : spec.command;
  const config = { command, args: (spec.args || []).map(fill) };
  const vars = Object.entries(spec.env || {}).map(([k, v]) => [k, fill(v)]).filter(([, v]) => v);
  if (vars.length) config.env = Object.fromEntries(vars);
  return [config, missing];
}

/**
 * KEY=VALUE lines (# comments, optional quotes) into process.env, never over a
 * variable already set. The file holds a client's settings and secret paths,
 * so it must not be readable by others.
 */
function loadEnvFile(file) {
  const st = fs.statSync(file);
  if (st.mode & 0o077) die(`${file}: mode ${(st.mode & 0o777).toString(8)}; chmod 600 it`);
  for (const line of fs.readFileSync(file, "utf8").split("\n")) {
    const m = line.match(/^\s*(?:export\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*=\s*(.*?)\s*$/);
    if (!m || line.trim().startsWith("#")) continue;
    let v = m[2];
