 * Where the package runs: the daemon's Linux user (and its home) and the tool
 * prefix, from .fgopc.yaml `host` unless --user / --prefix say otherwise.
 */
function hostOf(pkg, opts = {}) {
  const h = pkg.ext.host || {};
  const user = opts.user || h.user || os.userInfo().username;
  const r = spawnSync("getent", ["passwd", user], { encoding: "utf8" });
  const f = (r.stdout || "").trim().split(":");
  if (f.length < 6) die(`host user ${q(user)} does not exist on this machine`);
  return { user, uid: Number(f[2]), gid: Number(f[3]), home: f[5], prefix: path.resolve(opts.prefix || h.prefix || DEFAULT_PREFIX) };
}

/** ${VAR}, ${VAR:-default} and ${file:<name>} (a `files` entry's path on the host). */
function filler(pkg, host, env, missing) {
  const fill = (s) => String(s).replace(/\$\{(file:)?([A-Za-z_][A-Za-z0-9_-]*)(:-([^}]*))?\}/g, (m, file, name, dflt, value) => {
    if (file) {
      const f = pkg.secretFiles[name] || die(`\${file:${name}}: no files.${name} in .fgopc.yaml`);
      return path.join(host.home, fill(f.to));
    }
    if (env[name]) return env[name];
    if (dflt === undefined) missing.push(name);
    return value ?? "";
