async function main() {
  const { values: opts, positionals } = parseArgs({
    allowPositionals: true,
    options: {
      out: { type: "string", short: "o" },
      target: { type: "string", default: "multica" },
      "activate-routines": { type: "boolean", default: false },
      prefix: { type: "string" },
      user: { type: "string" },
      env: { type: "string" },
      check: { type: "boolean", default: false },
      help: { type: "boolean", short: "h" },
    },
  });
  const [cmd, dir] = positionals;
  if (opts.help) return console.log(USAGE);
  if (cmd === "client") {
    const [, sub, cdir] = positionals;
    if (!["plan", "deploy", "tools"].includes(sub) || !cdir || positionals.length > 3) {
      console.error(USAGE);
      process.exit(2);
    }
    return client(sub, cdir, opts);
  }
  if (!["lint", "pack", "plan", "deploy", "tools"].includes(cmd) || !dir || positionals.length > 2) {
    console.error(USAGE);
    process.exit(2);
  }
  if (opts.target !== "multica") die(`--target ${opts.target}: only 'multica' is supported`);
  if (opts.env) loadEnvFile(opts.env);
  const pkg = new Package(dir);
  const ok = printLint(pkg);
